const sources = [{"file":"rules/absent-digits.md","text":"---\nname: Absent Digits\nurl: https://rules.sudoku-sleuth.com/absent-digits.md\nkind: absent-digits\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2.\n    default: Required.\n    type: set<cell>\n  digits:\n    description: The digits that must be absent, for example [2,4].\n    default: Required.\n    type: list<digit>\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨d:d∈digits⟩:i∈[0,1)⟩\n  counts: ⟨|{}|:i∈[0,1)⟩\n  exhaustive: \"false\"\n  channel: '\"D\"'\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/aggregate-equation.md","text":"---\nname: Aggregate Equation\nurl: https://rules.sudoku-sleuth.com/aggregate-equation.md\nkind: aggregate-equation\nshape: Cages\nparameters:\n  left:\n    type: list<WeightedOperand>\n    description: Weighted, nonnegative integer powers of aggregate operands.\n    default: Required.\n  right:\n    type: list<WeightedOperand>\n    description: The right expression.\n    default: Required.\n  leftOperation:\n    type: enum{sum,product}\n    description: Combine left terms by sum or product.\n    default: sum.\n  rightOperation:\n    type: enum{sum,product}\n    description: Combine right terms by sum or product.\n    default: sum.\n  relation:\n    type: PairRelation\n    description: Relation on the expression results.\n    default: difference 0 (equal).\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nexpressionValid(left) ∧ expressionValid(right) ∧ pairRelation(relation,operandExpression(left,leftOperation),operandExpression(right,rightOperation))\n\n```\n"},{"file":"rules/aggregate-groups.md","text":"---\nname: Aggregate Groups\nurl: https://rules.sudoku-sleuth.com/aggregate-groups.md\nkind: aggregate-groups\nshape: Cages\nparameters:\n  groups:\n    type: list<list<cell>>\n    description: Occurrence lists to compare.\n    default: Required.\n  operation:\n    type: enum{sum,product,count,mean}\n    description: Aggregate to compare.\n    default: sum.\n  channel:\n    type: Channel\n    description: Read face digits D or effective values V.\n    default: D.\n  repeats:\n    type: boolean\n    description: Allow equal read values within each group.\n    default: true.\n  line:\n    type: optional<list<cell>>\n    description: Validate groups as maximal primary-region runs of this line.\n    default: Absent.\n  combine:\n    type: boolean\n    description: Combine separate visits to each primary region.\n    default: false.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nif present(line) then maximalRegionRuns(unwrap(line),groups) ∧ (if combine then equalAggregates({⟨c:c∈unwrap(line),c∈R⟩:R∈{S∈Regions:∃d∈unwrap(line):d∈S}},channel,operation,repeats) else equalAggregates(groups,channel,operation,repeats)) else equalAggregates(groups,channel,operation,repeats)\n\n```\n"},{"file":"rules/aggregate-relation.md","text":"---\nname: Aggregate Relation\nurl: https://rules.sudoku-sleuth.com/aggregate-relation.md\nkind: aggregate-relation\nalias_of: aggregate-equation\n---\n\n\n"},{"file":"rules/allowed-digits.md","text":"---\nname: Allowed Digits\nurl: https://rules.sudoku-sleuth.com/allowed-digits.md\nkind: allowed-digits\nparameters:\n  line:\n    description: The marked cells, listed with hyphens; their order does not affect this rule.\n    default: Required.\n    type: path<cell>\n  digits:\n    description: The permitted digits. Listing a digit does not require it to appear.\n    default: Required.\n    type: list<digit>\nalias_of: digit-profile\nalias_bind:\n  cells: line\n  classes: ⟨⟨d:d∈digits⟩:i∈[0,1)⟩\n  counts: ⟨|line|:i∈[0,1)⟩\n  exhaustive: \"false\"\n  channel: '\"D\"'\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/anti-king.md","text":"---\nname: Anti King\nurl: https://rules.sudoku-sleuth.com/anti-king.md\nkind: anti-king\nparameters: {}\nalias_of: relation-scope\nalias_bind:\n  cells: C\n  relations: ⟨relationSpec(\"difference\",0):i∈[0,1)⟩\n  mode: '\"incident\"'\n  move: '\"king\"'\n  anchors: \"{c∈C:D(c)∈𝔄}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"true\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/anti-knight.md","text":"---\nname: Anti Knight\nurl: https://rules.sudoku-sleuth.com/anti-knight.md\nkind: anti-knight\nparameters: {}\nalias_of: relation-scope\nalias_bind:\n  cells: C\n  relations: ⟨relationSpec(\"difference\",0):i∈[0,1)⟩\n  mode: '\"incident\"'\n  move: '\"knight\"'\n  anchors: \"{c∈C:D(c)∈𝔄}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"true\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/arrow.md","text":"---\nname: Arrow\nurl: https://rules.sudoku-sleuth.com/arrow.md\nkind: arrow\naliases: [Pill, Pill Arrow, Arrow Pill]\nparameters:\n  partial:\n    type: boolean\n    description: Whether the declaration supplies only a shaft fragment, for example under fog.\n    default: false (complete arrow).\n  bulb:\n    description: The bulb cells in decimal reading order, normally left to right or top to bottom.\n    default: Required.\n    type: list<cell>\n  line:\n    description: The shaft cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\nlayer: rule\n---\n\nClass: **existential**\n```text\n|bulb|>0 ∧ (|bulb|>1 → decimalValid(bulb)) ∧ let B=if |bulb|=1 then D(bulb[0]) else if decimalValid(bulb) then decimal(bulb) else 0;\n(partial → ∃remainder:list<digit>: |remainder|>0 ∧ (∀d∈remainder:d∈𝔄) ∧ aggregate(line,\"D\",\"sum\")+Σ_{d∈remainder}d=B)\n∧ (¬partial → (|bulb|=1 → aggregate(line,\"V\",\"sum\")=V(bulb[0])) ∧ (|bulb|!=1 → aggregate(line,\"D\",\"sum\")=B))\n\n```\n"},{"file":"rules/assignment.md","text":"---\nname: Assignment\nurl: https://rules.sudoku-sleuth.com/assignment.md\nkind: assignment\nshape: Global\nparameters:\n  name:\n    shared:\n      role: construct\n      type: assignment\n    type: string\n    description: The shared assignment name.\n    default: Required.\n  size:\n    type: position\n    description: Number of ordered slots.\n    default: Required.\n  labels:\n    type: position\n    description: Number of available labels.\n    default: Required.\n  bijective:\n    type: boolean\n    description: Require a bijection between slots and labels.\n    default: false.\nlayer: block\ncomposition: Shared label assignments over arbitrary ordered slots.\n---\n\nClass: **existential**\n```text\n(((((size >= 0) and (labels >= 0)) and (|assignmentAnswer(name)| = size)) and forall x∈assignmentAnswer(name): ((0 <= x) and (x < labels))) and (bijective implies ((size = labels) and allDifferent(assignmentAnswer(name),λx:position:x))))\n\n```\n"},{"file":"rules/battenburg.md","text":"---\nname: Battenburg\nurl: https://rules.sudoku-sleuth.com/battenburg.md\nkind: battenburg\nshape: Global\nparameters:\n  marks:\n    type: list<record{r:position,k:position}>\n    description: Zero-based top-left coordinates of marked squares.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Cells on which squares may lie.\n    default: Required.\n  mode:\n    type: enum{parity,selection}\n    description: The two-class source.\n    default: parity.\n  selectionRef:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: Selection name used in selection mode.\n    default: '\"H\".'\n  positive:\n    type: boolean\n    description: Require marked squares to alternate.\n    default: true.\n  exhaustive:\n    type: boolean\n    description: Forbid the pattern on unmarked squares inside scope.\n    default: false.\nlayer: rule\n---\n\nClass: **existential**\n```text\n(∀m∈marks:0<=m.r ∧ m.r<rows-1 ∧ 0<=m.k ∧ m.k<cols-1 ∧ window2(m.r,m.k)⊆scope) ∧ ∀r∈[0,rows-1): ∀k∈[0,cols-1): window2(r,k)⊆scope → let pattern=alternatingSquare(r,k,λc:cell:if mode=\"parity\" then odd(D(c)) else marked(selectionRef,c)); let shown=∃m∈marks:m.r=r ∧ m.k=k; (positive ∧ shown → pattern) ∧ (exhaustive ∧ ¬shown → ¬pattern)\n\n```\n"},{"file":"rules/between-line.md","text":"---\nname: Between Line\nurl: https://rules.sudoku-sleuth.com/between-line.md\nkind: between-line\naliases: [\"Between\"]\nparameters:\n  ends:\n    description: The two end cells, in their stated order.\n    default: Required.\n    type: list<cell>\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\nlayer: rule\nalias_of: endpoint-range\nalias_bind:\n  ends: ends\n  line: line\n  outside: \"false\"\n  gap: \"0\"\n---\n\n\n"},{"file":"rules/between.md","text":"---\nname: Between\nurl: https://rules.sudoku-sleuth.com/between.md\nkind: between\nalias_of: between-line\n---\n\n\n"},{"file":"rules/blocked-sight.md","text":"---\nname: Blocked Sight\nurl: https://rules.sudoku-sleuth.com/blocked-sight.md\nkind: blocked-sight\nshape: Outside\nparameters:\n  cell:\n    type: optional<cell>\n    description: The sight origin.\n    default: Absent; required for origin-dependent modes.\n  rays:\n    type: list<list<cell>>\n    description: Ordered rays, nearest first, each excluding the origin.\n    default: Required.\n  blockers:\n    type: set<cell>\n    description: Fixed blockers for listed mode.\n    default: Empty set.\n  includeBlocker:\n    type: boolean\n    description: Include the first blocker.\n    default: false.\n  includeOrigin:\n    type: boolean\n    description: Include the origin once across all rays.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  offset:\n    type: number\n    description: Add this offset to the count or sum.\n    default: \"0.\"\n  output:\n    type: enum{count,sum}\n    description: Count selected cells or sum their numbers.\n    default: Required.\n  records:\n    type: boolean\n    description: Keep only record highs within each unblocked ray.\n    default: false.\n  total:\n    type: optional<number>\n    description: A fixed target, replacing the origin or target-cell total.\n    default: Absent; use targetCells or the origin number.\n  blocking:\n    type: SightBlock\n    description: Block at listed cells, different parity, different shading colour, a different primary region, greater or at-least numbers, or numbers unequal to the origin.\n    default: listed.\n  targetCells:\n    type: list<cell>\n    description: The cells whose numbers supply the target sum.\n    default: Empty list; use the origin number.\n  occurrences:\n    type: boolean\n    description: Count ray occurrences instead of deduplicated cells.\n    default: false.\nlayer: block\ncomposition: Arbitrary rays, listed or value blockers, counts or totals, and origin/blocker inclusion.\n---\n\nClass: **existential**\n```text\nif occurrences then records ∧ blocking=\"listed\" ∧ |blockers|=0 ∧ ¬includeOrigin ∧ present(total) ∧ Σ_{ray∈rays} |visibleRecords(ray,channel)|+offset=unwrap(total) else present(cell) ∧ ((∀ray∈rays:unwrap(cell)∉ray) ∧ (blocking=\"different-parity\" → ∀c∈C: ⌊read(c,channel)⌋=read(c,channel)) ∧ let selected={c∈C: (includeOrigin ∧ c=unwrap(cell)) ∨ ∃ray∈rays: let prefix=blockedPrefix(ray,λb:cell:sightBlock(unwrap(cell),b,blocking,blockers,channel),includeBlocker); if records then c∈visibleRecords(prefix,channel) else c∈prefix};\naggregate(selected,channel,output)+offset=(if present(total) then unwrap(total) else if |targetCells|>0 then aggregate(targetCells,channel,\"sum\") else read(unwrap(cell),channel)))\n\n```\n"},{"file":"rules/bremban.md","text":"---\nname: Bremban\nurl: https://rules.sudoku-sleuth.com/bremban.md\nkind: bremban\nparameters:\n  line:\n    description: The marked cells; order does not affect the consecutive set.\n    default: Required.\n    type: path<cell>\n    empty_when: edges\n  edges:\n    type: optional<list<list<cell>>>\n    description: The edges of a connected network.\n    default: Absent; use the listed cells.\n  selection:\n    type: optional<PrefixSelection>\n    description: A stopping prefix of the ordered list.\n    default: Absent; use the whole cell set.\nalias_of: value-set\nalias_bind:\n  line: line\n  edges: edges\n  channel: '\"D\"'\n  repeats: \"true\"\n  selection: selection\n  mode: '\"consecutive\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/cage-expressions.md","text":"---\nname: Cage Expressions\nurl: https://rules.sudoku-sleuth.com/cage-expressions.md\nkind: cage-expressions\nparameters:\n  cages:\n    description: The cells in each cage and its expression or relation, as stated in the definition.\n    default: Required.\n    type: list<record{cells:set<cell>,expression:expression}>\n  distinct:\n    description: Whether different letters must have different values.\n    default: Required.\n    type: boolean\nlayer: rule\n---\n\nClass: **existential**\n```text\n∃letterValues:list<position>:\n  |letterValues|=letterCount({g.expression:g∈cages}) ∧\n  (∀g∈cages: defined(g.expression,letterValues) ∧ eval(g.expression,letterValues)=aggregate(g.cells,\"D\",\"sum\"))\n  ∧ (distinct → ∀i,j∈[0,|letterValues|): i!=j → letterValues[i]!=letterValues[j])\n\n```\n"},{"file":"rules/cage-pair.md","text":"---\nname: Cage Pair\nurl: https://rules.sudoku-sleuth.com/cage-pair.md\nkind: cage-pair\nparameters:\n  relation:\n    description: 'The relationship to enforce: its operation and any required value, for example {\"op\":\"difference\",\"value\":1}.'\n    default: Required.\n    type: PairRelation\n  cages:\n    description: The cells in each cage and its expression or relation, as stated in the definition.\n    default: Required.\n    type: list<set<cell>>\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨weightedOperand(aggregateOperand(if |cages|=2 then orderedCells(cages[0]) else ⟨c:c∈orderedCells(C),false⟩,\"D\",\"sum\",true),1,1):termIndex∈[0,1)⟩\n  right: ⟨weightedOperand(aggregateOperand(if |cages|=2 then orderedCells(cages[1]) else ⟨c:c∈orderedCells(C),false⟩,\"D\",\"sum\",true),1,1):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: if |cages|=2 then relation else relationSpec(\"difference\",-1)\nlayer: rule\n---\n\n\n"},{"file":"rules/cage-shapes.md","text":"---\nname: Cage Shapes\nurl: https://rules.sudoku-sleuth.com/cage-shapes.md\nkind: cage-shapes\nparameters:\n  size:\n    description: The number of cells in each constructed region or cage.\n    default: Required.\n    type: position\n  hidden:\n    description: \"Each hidden cage: its clue cell, total and known member cells.\"\n    default: Required.\n    type: list<record{clue:cell,sum:number,known:set<cell>}>\n  free:\n    allow_empty: true\n    description: Cells excluded from all hidden cages.\n    default: Required.\n    type: set<cell>\nlayer: rule\n---\n\nClass: **existential**\n```text\n∃chosen:list<set<cell>>:\n  |chosen|=|hidden|\n  ∧ (∀i∈[0,|hidden|): let h=hidden[i]; let cageSet=chosen[i];\n    |cageSet|=size ∧ cageSet⊆C ∧ connected(cageSet) ∧ h.known⊆cageSet\n    ∧ cageSet∩free=∅ ∧ h.clue∈cageSet ∧ (∀c∈cageSet: cellIndex(h.clue)<=cellIndex(c))\n    ∧ repeatPolicy(cageSet,\"D\",false) ∧ aggregate(cageSet,\"D\",\"sum\")=h.sum)\n  ∧ (∀i,j∈[0,|hidden|): i!=j → chosen[i]∩chosen[j]=∅)\n\n```\n"},{"file":"rules/cage.md","text":"---\nname: Cage\nurl: https://rules.sudoku-sleuth.com/cage.md\nkind: cage\naliases: [Killer Cage, Killer]\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  total:\n    description: The total the digits or values must add up to.\n    default: No total imposed.\n    type: optional<number>\n  repeats:\n    description: Whether repeated digits are allowed.\n    default: false (distinct digits).\n    type: boolean\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨if termIndex=0 then weightedOperand(aggregateOperand(orderedCells(cells),\"D\",\"count\",repeats),0,1) else weightedOperand(aggregateOperand(orderedCells(cells),channel,\"sum\",true),if present(total) then 1 else 0,1):termIndex∈[0,2)⟩\n  right: ⟨weightedOperand(aggregateOperand(⟨c:c∈orderedCells(C),false⟩,\"D\",\"count\",true),if present(total) then unwrap(total) else 0,0):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: relationSpec(\"difference\",0)\nlayer: rule\n---\n\n\n"},{"file":"rules/cell-entries.md","text":"---\nname: Cell Entries\nurl: https://rules.sudoku-sleuth.com/cell-entries.md\nkind: cell-entries\nshape: Cells\nparameters:\n  name:\n    shared:\n      role: construct\n      type: symbol\n    type: string\n    description: Shared symbol channel name.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Cells whose entries are constrained.\n    default: Required.\n  minimum:\n    type: position\n    description: Minimum entries per cell.\n    default: \"1.\"\n  maximum:\n    type: position\n    description: Maximum entries per cell.\n    default: \"1.\"\n  distinct:\n    type: boolean\n    description: Require distinct symbols within each cell.\n    default: true.\n  faceMode:\n    type: enum{independent,sum,first}\n    description: Relationship to the face digit D.\n    default: independent.\nlayer: block\ncomposition: Shared symbol lists with configurable size and multiplicity.\n---\n\nClass: **existential**\n```text\nname!=\"D\" ∧ name!=\"V\" ∧ minimum>=0 ∧ maximum>=minimum ∧ ∀c∈scope: let xs=symbolAnswer(name,c); minimum<=|xs| ∧ |xs|<=maximum ∧ (∀d∈xs:d∈𝔄) ∧ (distinct → allDifferent(xs,λd:digit:d)) ∧ (faceMode=\"sum\" → D(c)=Σ_{d∈xs}d) ∧ (faceMode=\"first\" → |xs|>0 ∧ D(c)=xs[0])\n\n```\n"},{"file":"rules/choice-count.md","text":"---\nname: Choice Count\nurl: https://rules.sudoku-sleuth.com/choice-count.md\nkind: choice-count\nshape: Global\nparameters:\n  choices:\n    shared:\n      role: read\n      type: choice\n    type: list<string>\n    description: Distinct shared truth labels.\n    default: Required.\n  minimum:\n    type: position\n    description: Minimum true labels.\n    default: \"0.\"\n  maximum:\n    type: optional<position>\n    description: Maximum true labels.\n    default: Absent; no upper bound.\nlayer: block\ncomposition: Boolean composition over arbitrary labelled constraints.\n---\n\nClass: **existential**\n```text\n(∀i,j∈[0,|choices|):i!=j → choices[i]!=choices[j]) ∧ minimum>=0 ∧ countWhere(choices,λs:string:choiceAnswer(s))>=minimum ∧ (present(maximum) → unwrap(maximum)>=minimum ∧ countWhere(choices,λs:string:choiceAnswer(s))<=unwrap(maximum))\n\n```\n"},{"file":"rules/class-pattern.md","text":"---\nname: Class Pattern\nurl: https://rules.sudoku-sleuth.com/class-pattern.md\nkind: class-pattern\nshape: Lines\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Empty list.\n    type: list<cell>\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  classification:\n    type: enum{residue,entropy}\n    description: Use integer residues or equal thirds of the alphabet.\n    default: residue.\n  modulus:\n    type: position\n    description: Number of residue classes.\n    default: \"3.\"\n  length:\n    type: position\n    description: Number of cells in each distinct-class window.\n    default: \"3.\"\n  geometry:\n    type: enum{line,cells,squares}\n    description: Select line windows, the whole supplied list, or board 2 by 2 squares.\n    default: line.\n  mode:\n    type: enum{distinct,same,cover}\n    description: Require different classes, one shared class, or every class.\n    default: distinct.\n  fixedClass:\n    type: optional<position>\n    description: Require this residue at every listed cell instead of comparing windows.\n    default: Absent.\n  channel:\n    type: Channel\n    description: Channel for fixed residue classes.\n    default: D.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nif present(fixedClass) then modulus>=1 ∧ (∀c∈line: ⌊read(c,channel)⌋=read(c,channel) ∧ rem(read(c,channel),modulus)=unwrap(fixedClass)) else classPattern(line,edges,loop,classification,modulus,length,geometry,mode)\n\n```\n"},{"file":"rules/clone.md","text":"---\nname: Clone\nurl: https://rules.sudoku-sleuth.com/clone.md\nkind: clone\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nalias_of: relation-scope\nalias_bind:\n  cells: cells\n  relations: ⟨relationSpec(\"difference\",0):i∈[0,1)⟩\n  mode: '\"all\"'\n  move: '\"orthogonal\"'\n  anchors: \"{}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"false\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/close-whispers.md","text":"---\nname: Close Whispers\nurl: https://rules.sudoku-sleuth.com/close-whispers.md\nkind: close-whispers\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  gap:\n    description: The greatest difference allowed between neighbours.\n    default: Required.\n    type: number\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: difference-line\nalias_bind:\n  line: line\n  edges: edges\n  loop: \"false\"\n  mode: '\"at-most\"'\n  channel: channel\n  diamonds: \"{}\"\n  gap: gap\n  turnDigits: \"{}\"\nlayer: rule\n---\n\n\n"},{"file":"rules/clue-count.md","text":"---\nname: Lying Clues\nurl: https://rules.sudoku-sleuth.com/clue-count.md\nkind: clue-count\nshape: Global\nlayer: rule\nparameters:\n  clues:\n    type: list<clause>\n    description: The complete clues in this count's scope.\n    default: Required.\n  comparison:\n    type: enum{exactly,\"at-least\",\"at-most\"}\n    description: How to compare the number of false clues with count.\n    default: Required.\n  count:\n    type: position\n    description: The nonnegative number of false clues.\n    default: Required.\n---\n\nClass: **with aggregates**\n```text\nlet failures=countWhere(clues,λq:clause: ¬clueHolds(q));\n(comparison=\"exactly\" → failures=count)\n∧ (comparison=\"at-least\" → failures>=count)\n∧ (comparison=\"at-most\" → failures<=count)\n\n```\n"},{"file":"rules/constructed-regions.md","text":"---\nname: Constructed Regions\nurl: https://rules.sudoku-sleuth.com/constructed-regions.md\nkind: constructed-regions\nparameters:\n  size:\n    description: The number of cells in each constructed region or cage.\n    default: Required.\n    type: position\n  borders:\n    allow_empty: true\n    description: Pairs of neighbouring cells that must belong to different regions.\n    default: Required.\n    type: list<list<cell>>\n  joins:\n    allow_empty: true\n    description: Pairs of cells that must belong to the same region.\n    default: Required.\n    type: list<list<cell>>\nalias_of: region-partition\nalias_bind:\n  name: '\"\"'\n  scope: C\n  sizes: ⟨size:i∈[0,1)⟩\n  count: absent(|C|)\n  distinct: \"true\"\n  channel: '\"D\"'\n  joins: joins\n  borders: borders\n  separation: absent(\"orthogonal\")\nlayer: rule\n---\n\n\n"},{"file":"rules/coordinate-arrows.md","text":"---\nname: Coordinate Arrows\nurl: https://rules.sudoku-sleuth.com/coordinate-arrows.md\nkind: coordinate-arrows\nparameters:\n  arrows:\n    description: The base and tip cells of each arrow, one ordered pair per arrow.\n    default: Required.\n    type: list<list<cell>>\nlayer: rule\n---\n\nClass: **first-order**\n```text\n(∀p∈arrows: |p|=2 ∧ let a=D(p[0]); let b=D(p[1]);\n  1<=a<=rows ∧ 1<=b<=cols ∧ D(boardCell(a-1,b-1))=a+b)\n∧ (∀i,j∈[0,|arrows|): i!=j → |arrows[i]|=2 ∧ |arrows[j]|=2\n  ∧ (D(arrows[i][0])!=D(arrows[j][0]) ∨ D(arrows[i][1])!=D(arrows[j][1])))\n\n```\n"},{"file":"rules/coordinate-count.md","text":"---\nname: Coordinate Count\nurl: https://rules.sudoku-sleuth.com/coordinate-count.md\nkind: coordinate-count\nshape: Cells\nparameters:\n  sources:\n    type: list<cell>\n    description: Source occurrences supplying coordinate indices.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Allowed destination cells.\n    default: Required.\n  rowBase:\n    type: number\n    description: Zero-based row before adding the transformed index.\n    default: 0\n  colBase:\n    type: number\n    description: Zero-based column before adding the transformed index.\n    default: 0\n  rowFactor:\n    type: number\n    description: Multiply the offset index by this row coefficient.\n    default: 0\n  colFactor:\n    type: number\n    description: Multiply the offset index by this column coefficient.\n    default: 1\n  offset:\n    type: number\n    description: Add this integer before applying the coordinate coefficients.\n    default: -1\n  indexChannel:\n    type: Channel\n    description: Channel supplying the coordinate index.\n    default: D.\n  channel:\n    type: Channel\n    description: Channel supplying destination numbers.\n    default: D.\n  target:\n    type: number\n    description: The destination comparison target.\n    default: Required.\n  relation:\n    type: PairRelation\n    description: Relation from the destination number to the target.\n    default: difference 0 (equal).\n  total:\n    type: position\n    description: Required number of successful source occurrences.\n    default: Required.\nlayer: block\ncomposition: Configurable coordinate transforms and destination counts.\n---\n\nClass: **with aggregates**\n```text\nintegerCoordinates(rowBase,colBase,rowFactor,colFactor,offset) ∧ total=countWhere(sources,λs:cell:coordinateHit(s,scope,rowBase,colBase,rowFactor,colFactor,offset,indexChannel,channel,target,relation))\n\n```\n"},{"file":"rules/counting-circles.md","text":"---\nname: Counting Circles\nurl: https://rules.sudoku-sleuth.com/counting-circles.md\nkind: counting-circles\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨0:i∈[0,0)⟩:j∈[0,0)⟩\n  counts: ⟨|C|:i∈[0,0)⟩\n  exhaustive: \"false\"\n  channel: '\"D\"'\n  selfCount: \"true\"\n  windowLength: absent(|C|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/decoration.md","text":"---\nname: Decoration\nurl: https://rules.sudoku-sleuth.com/decoration.md\nkind: decoration\nshape: cells\nparameters:\n  cells:\n    type: set<cell>\n    description: The cells covered by the decorative marks, including every cell of a marked region.\n    default: Required.\n  note:\n    type: string\n    description: A description of which marks to ignore.\n    default: Omitted.\nlayer: block\ncomposition: Case drawing metadata and overlap ownership.\n---\n\nClass: **first-order**\n```text\ntrue\n\n```\n"},{"file":"rules/derived-count.md","text":"---\nname: Derived Count\nurl: https://rules.sudoku-sleuth.com/derived-count.md\nkind: derived-count\nshape: Cages\nparameters:\n  quantities:\n    type: list<DerivedQuantity>\n    description: Ordered aggregate pairs and their sum, product, absolute difference or directed ratio.\n    default: Required.\n  mode:\n    type: enum{matches,distinct,rank}\n    description: Count matches, distinct results, or one plus the number of smaller results.\n    default: matches.\n  target:\n    type: number\n    description: Comparison target; unused in distinct mode.\n    default: \"0.\"\n  relation:\n    type: PairRelation\n    description: Relation from each result to the target in matches mode.\n    default: difference 0 (equal).\n  total:\n    type: position\n    description: Required count or rank.\n    default: Required.\nlayer: block\ncomposition: Count or rank results of arbitrary operand-pair computations.\n---\n\nClass: **with aggregates**\n```text\n(∀q∈quantities: quantityValid(q)) ∧ (if mode=\"distinct\" then total=|{quantity(q):q∈{x∈quantities:quantityValid(x)}}| else if mode=\"rank\" then total=1+countWhere(quantities,λq:DerivedQuantity:quantityValid(q) ∧ quantity(q)<target) else total=countWhere(quantities,λq:DerivedQuantity:quantityValid(q) ∧ pairRelation(relation,quantity(q),target)))\n\n```\n"},{"file":"rules/diagonal-lines.md","text":"---\nname: Diagonal Lines\nurl: https://rules.sudoku-sleuth.com/diagonal-lines.md\nkind: diagonal-lines\nparameters:\n  classes:\n    description: \"The digit classes to use: parity, remainder or alphabet thirds.\"\n    default: Required.\n    type: ClassSystem\n  minLength:\n    description: The shortest diagonal covered by the rule.\n    default: Required.\n    type: number\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n(classes!=\"entropy\" ∨ (|𝔄|>0 ∧ |𝔄| mod 3=0))\n∧ ∀L∈boardDiagonals(): |L|>=maximumPair(3,minLength) →\n  ((∃k∈classIds(classes): ∀c∈L: digitClass(classes,D(c))=k)\n   ∨ (∀s∈[0,|L|-|classIds(classes)|+1):\n     allDifferent(window(L,|classIds(classes)|,s,false),λc:cell: digitClass(classes,D(c)))))\n\n```\n"},{"file":"rules/diagonal-sum.md","text":"---\nname: Diagonal Sum\nurl: https://rules.sudoku-sleuth.com/diagonal-sum.md\nkind: diagonal-sum\nshape: Outside\naliases: [Little Killer]\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  sum:\n    description: The total the digits or values must add up to.\n    default: Required.\n    type: number\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  repeats:\n    type: boolean\n    description: Whether numbers may repeat on the ray.\n    default: true.\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨weightedOperand(aggregateOperand(cells,channel,\"sum\",repeats),1,1):termIndex∈[0,1)⟩\n  right: ⟨weightedOperand(aggregateOperand(⟨c:c∈orderedCells(C),false⟩,\"D\",\"count\",true),sum,0):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: relationSpec(\"difference\",0)\nlayer: rule\n---\n\n\n"},{"file":"rules/diagonal.md","text":"---\nname: Diagonal\nurl: https://rules.sudoku-sleuth.com/diagonal.md\nkind: diagonal\nparameters:\n  direction:\n    description: The chosen diagonal or neighbour orientation, as named in the definition.\n    default: Required.\n    type: enum{main,anti}\nalias_of: relation-scope\nalias_bind:\n  cells: diagonal(direction)\n  relations: ⟨relationSpec(\"difference\",0):i∈[0,1)⟩\n  mode: '\"all\"'\n  move: '\"orthogonal\"'\n  anchors: \"{}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"true\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/difference-line.md","text":"---\nname: Difference Line\nurl: https://rules.sudoku-sleuth.com/difference-line.md\nkind: difference-line\nshape: Lines\nparameters:\n  line:\n    empty_when: edges\n    type: path<cell>\n    description: The ordered line; supply an empty list when edges describe a network.\n    default: Required.\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  loop:\n    type: boolean\n    description: Include the last-to-first edge.\n    default: false.\n  mode:\n    type: enum{same,different,\"signed-step\",\"at-least\",\"at-most\",turning}\n    description: Compare edge differences with each other, or with gap.\n    default: Required.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  diamonds:\n    type: set<cell>\n    description: Clue cells equal to the common absolute difference.\n    default: Empty set.\n  gap:\n    type: number\n    description: Bound for at-least and at-most modes.\n    default: \"0.\"\n  turnDigits:\n    type: set<number>\n    description: Values at which successive differences must change sign in turning mode.\n    default: Empty set.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nif mode=\"turning\" then lineGeometry(line,edges,loop)\n∧ (∀W∈lineWindows(line,edges,2,loop): |W|=2 → read(W[0],channel)!=read(W[1],channel))\n∧ ∀W∈lineWindows(line,edges,3,loop): |W|=3 →\n  ((read(W[1],channel)∈turnDigits → (read(W[1],channel)-read(W[0],channel))*(read(W[2],channel)-read(W[1],channel))<0)\n  ∧ (read(W[1],channel)∉turnDigits → (read(W[1],channel)-read(W[0],channel))*(read(W[2],channel)-read(W[1],channel))>0)) else if mode=\"at-least\" ∨ mode=\"at-most\" then lineGeometry(line,edges,loop) ∧ |diamonds|=0 ∧ ∀W∈lineWindows(line,edges,2,loop): |W|=2 → (if mode=\"at-least\" then edgeDifference(W,channel)>=gap else edgeDifference(W,channel)<=gap) else lineGeometry(line,edges,loop) ∧ let W=lineWindows(line,edges,2,loop); |W|>0 ∧\n(mode=\"signed-step\" → ¬present(edges) ∧ |diamonds|=0 ∧ ∀p,q∈W: |p|=2 ∧ |q|=2 → read(p[1],channel)-read(p[0],channel)=read(q[1],channel)-read(q[0],channel))\n∧ (mode!=\"signed-step\" → (∀p,q∈W: |p|=2 ∧ |q|=2 → ((mode=\"same\" → |read(p[0],channel)-read(p[1],channel)|=|read(q[0],channel)-read(q[1],channel)|) ∧ (mode=\"different\" ∧ {p[0],p[1]}!={q[0],q[1]} → |read(p[0],channel)-read(p[1],channel)|!=|read(q[0],channel)-read(q[1],channel)|))) ∧ (mode=\"different\" → |diamonds|=0) ∧ (mode=\"same\" → ∀g∈diamonds: ∀p∈W: |p|=2 → read(g,channel)=|read(p[0],channel)-read(p[1],channel)|))\n\n```\n"},{"file":"rules/digit-profile.md","text":"---\nname: Digit Profile\nurl: https://rules.sudoku-sleuth.com/digit-profile.md\nkind: digit-profile\nshape: Cages\nparameters:\n  cells:\n    type: list<cell>\n    description: The occurrences to count.\n    default: Required.\n  classes:\n    allow_empty: true\n    type: list<list<number>>\n    description: Arbitrary numeric classes; a class may overlap another.\n    default: Required.\n  counts:\n    allow_empty: true\n    type: list<position>\n    description: Required count for each class, in the same order.\n    default: Required.\n  exhaustive:\n    type: boolean\n    description: Require every read number to belong to at least one class.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  selfCount:\n    type: boolean\n    description: Require every occurring number to equal its own frequency.\n    default: false.\n  windowLength:\n    type: optional<position>\n    description: Apply class counts to every full window of this length.\n    default: Absent; count over the whole list.\n  loop:\n    type: boolean\n    description: Include cyclic windows when windowLength is present.\n    default: false.\n  comparison:\n    type: enum{exact,\"at-least\"}\n    description: Compare each class frequency exactly or by a lower bound.\n    default: exact.\n  maximumDistinct:\n    type: optional<number>\n    description: Largest permitted number of different read values.\n    default: Absent; no bound.\n  repeats:\n    type: boolean\n    description: Allow equal read values in the whole occurrence list.\n    default: true.\n  balancePairs:\n    type: list<list<number>>\n    description: Adjacent pairs of numeric classes whose frequencies must match.\n    default: Empty list.\n  sumFree:\n    type: optional<position>\n    description: Forbid sums of two members modulo this positive modulus from the support.\n    default: Absent.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\n((|classes|=|counts| ∧ (∀n∈counts:n>=0) ∧ repeatPolicy(cells,channel,repeats) ∧ (present(maximumDistinct) → |{read(c,channel):c∈cells}|<=unwrap(maximumDistinct)) ∧ (selfCount → ownFrequencies(cells,channel)) ∧ (if present(windowLength) then classWindows(cells,classes,counts,unwrap(windowLength),loop,channel,comparison) else classProfile(cells,classes,counts,channel,comparison)) ∧ (exhaustive → ∀c∈cells: ∃ns∈classes:read(c,channel)∈ns)) ∧ |balancePairs| mod 2=0 ∧ (∀i∈[0,|balancePairs|): i<⌊|balancePairs|/2⌋ → 0<=2*i ∧ 2*i<|balancePairs| ∧ 0<=2*i+1 ∧ 2*i+1<|balancePairs| ∧ classCount(cells,balancePairs[2*i],channel)=classCount(cells,balancePairs[2*i+1],channel))) ∧ (present(sumFree) → unwrap(sumFree)>=1 ∧ ⌊unwrap(sumFree)⌋=unwrap(sumFree) ∧ (∀c∈cells: ⌊read(c,channel)⌋=read(c,channel)) ∧ repeatPolicy(cells,channel,repeats) ∧ (∀a,b,c∈cells: ⌊(read(a,channel)+read(b,channel))⌋=read(a,channel)+read(b,channel) ∧ rem(read(a,channel)+read(b,channel),unwrap(sumFree))!=read(c,channel)))\n\n```\n"},{"file":"rules/doll-sum.md","text":"---\nname: Doll Sum\nurl: https://rules.sudoku-sleuth.com/doll-sum.md\nkind: doll-sum\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  sums:\n    description: The permitted or required totals.\n    default: Required.\n    type: list<number>\nlayer: rule\nalias_of: selected-stretch\nalias_bind:\n  cells: cells\n  selection: '\"balanced\"'\n  sum: \"0\"\n  count: absent(|{}|)\n  sums: sums\n  crusts: absent(⟨d:d∈𝔄⟩)\n  endpointOccurrences: '\"none\"'\n---\n\n\n"},{"file":"rules/double-arrow.md","text":"---\nname: Double Arrow\nurl: https://rules.sudoku-sleuth.com/double-arrow.md\nkind: double-arrow\nparameters:\n  ends:\n    description: The two end cells, in their stated order.\n    default: Required.\n    type: list<cell>\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  repeats:\n    type: boolean\n    description: Whether numbers may repeat in the listed ends and interior.\n    default: true.\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨if termIndex=0 then weightedOperand(aggregateOperand(line,channel,\"sum\",true),1,1) else weightedOperand(aggregateOperand(⟨if i<|ends| then ends[i] else line[i-|ends|]:i∈[0,|ends|+|line|)⟩,channel,\"count\",repeats),0,1):termIndex∈[0,2)⟩\n  right: ⟨weightedOperand(aggregateOperand(ends,channel,\"sum\",true),1,1):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: if |ends|=2 then relationSpec(\"difference\",0) else relationSpec(\"difference\",-1)\nlayer: rule\n---\n\n\n"},{"file":"rules/endpoint-range.md","text":"---\nname: Endpoint Range\nurl: https://rules.sudoku-sleuth.com/endpoint-range.md\nkind: endpoint-range\nlayer: block\nparameters:\n  ends:\n    type: list<cell>\n    description: The two endpoints.\n    default: Required.\n  line:\n    type: path<cell>\n    description: Interior cells in drawing order.\n    default: Required.\n  outside:\n    type: boolean\n    description: Use the complement of the closed interval.\n    default: false.\n  gap:\n    type: number\n    description: Minimum endpoint difference when outside is true.\n    default: \"0.\"\n---\n\nClass: **first-order**\n```text\n|ends|=2 ∧ (if outside then pairRelation(relationSpec(\"at-least\",gap),D(ends[0]),D(ends[1])) ∧ (∀c∈line: ¬numericBetween(D(c),D(ends[0]),D(ends[1]),true)) else ∀c∈line: numericBetween(D(c),D(ends[0]),D(ends[1]),false))\n\n```\n"},{"file":"rules/entropic.md","text":"---\nname: Entropic\nurl: https://rules.sudoku-sleuth.com/entropic.md\nkind: entropic\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the path closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: class-pattern\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  classification: '\"entropy\"'\n  modulus: \"3\"\n  length: \"3\"\n  geometry: '\"line\"'\n  mode: '\"distinct\"'\n  fixedClass: absent(|{}|)\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/equal-sums.md","text":"---\nname: Equal Sums\nurl: https://rules.sudoku-sleuth.com/equal-sums.md\nkind: equal-sums\nparameters:\n  groups:\n    description: The cells in each group, one list per group.\n    default: Required.\n    type: list<set<cell>>\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  repeats:\n    type: boolean\n    description: Whether numbers may repeat within each group.\n    default: true.\nalias_of: aggregate-groups\nalias_bind:\n  groups: ⟨orderedCells(S):S∈groups⟩\n  operation: '\"sum\"'\n  channel: channel\n  repeats: repeats\n  line: absent(orderedCells(C))\n  combine: \"false\"\nlayer: rule\n---\n\n\n"},{"file":"rules/equality-cage.md","text":"---\nname: Equality Cage\nurl: https://rules.sudoku-sleuth.com/equality-cage.md\nkind: equality-cage\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nlayer: rule\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨d:d∈𝔄,d!=(|𝔄|+1)/2⟩:i∈[0,1)⟩\n  counts: ⟨|cells|:i∈[0,1)⟩\n  exhaustive: \"true\"\n  channel: '\"D\"'\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"false\"\n  balancePairs: ⟨⟨d:d∈𝔄,(if i<2 then (d<(|𝔄|+1)/2 ∧ odd(d)) ∨ (d>(|𝔄|+1)/2 ∧ ¬odd(d)) else (d<(|𝔄|+1)/2 ∧ ¬odd(d)) ∨ (d>(|𝔄|+1)/2 ∧ odd(d))) ∧ (if i mod 2=0 then d<(|𝔄|+1)/2 else d>(|𝔄|+1)/2)⟩:i∈[0,4)⟩\n  sumFree: absent(|{}|)\n---\n\n\n"},{"file":"rules/extra-regions.md","text":"---\nname: Extra Regions\nurl: https://rules.sudoku-sleuth.com/extra-regions.md\nkind: extra-regions\nalias_of: regions\n---\n\n\n"},{"file":"rules/extremum.md","text":"---\nname: Extremum\nurl: https://rules.sudoku-sleuth.com/extremum.md\nkind: extremum\nparameters:\n  type:\n    description: The mode named in the definition, such as min or max.\n    default: Required.\n    type: enum{min,max}\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  exhaustive:\n    description: Whether every occurrence is marked, so unmarked cells obey the opposite condition.\n    default: Required.\n    type: boolean\n  neighbourhood:\n    type: Move\n    description: The move defining neighbours.\n    default: orthogonal.\n  boundary:\n    type: boolean\n    description: Compare marked cells only with neighbours outside the marked set.\n    default: true.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  neighbours:\n    type: optional<set<cell>>\n    description: Explicit comparison neighbours, replacing move-selected neighbours.\n    default: Absent.\nlayer: rule\nalias_of: neighbour-extremum\nalias_bind:\n  type: type\n  cells: cells\n  exhaustive: exhaustive\n  neighbourhood: neighbourhood\n  boundary: boundary\n  channel: channel\n  neighbours: neighbours\n---\n\n\n"},{"file":"rules/flat-mates.md","text":"---\nname: Flat Mates\nurl: https://rules.sudoku-sleuth.com/flat-mates.md\nkind: flat-mates\nparameters:\n  digit:\n    description: The specified digit.\n    default: Required.\n    type: digit\n  above:\n    description: The digit immediately above the marked digit.\n    default: Required.\n    type: digit\n  below:\n    description: The digit immediately below the marked digit.\n    default: Required.\n    type: digit\nlayer: rule\n---\n\nClass: **first-order**\n```text\n∀c ∈ C: D(c)=digit → ∃a ∈ C: (aboveCell(a,c) ∧ D(a)=above) ∨ (aboveCell(c,a) ∧ D(a)=below)\n\n```\n"},{"file":"rules/greek-carpet.md","text":"---\nname: Greek Carpet\nurl: https://rules.sudoku-sleuth.com/greek-carpet.md\nkind: greek-carpet\nparameters:\n  line:\n    description: The rolled path in order from its corresponding starting end.\n    default: Required.\n    type: path<cell>\n  unrolled:\n    description: The corresponding cells on the unrolled path, in order.\n    default: Required.\n    type: list<cell>\nlayer: rule\n---\n\nClass: **first-order**\n```text\n|line|=|unrolled| ∧ ∀i∈[0,|line|): D(line[i])=D(unrolled[i])\n\n```\n"},{"file":"rules/hidden-modular.md","text":"---\nname: Hidden Modular\nurl: https://rules.sudoku-sleuth.com/hidden-modular.md\nkind: hidden-modular\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  extent:\n    description: \"How to choose the span: to-max, between-ends or first-x.\"\n    default: Required.\n    type: enum{\"to-max\",\"between-ends\",\"first-x\"}\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n|𝔄|>0 ∧ ∃a,b∈[0,|cells|):\n  a<=b ∧ ((extent=\"to-max\" ∧ a=0 ∧ firstOccurrence(cells,𝔄[|𝔄|-1],b))\n    ∨ (extent=\"between-ends\" ∧ ∃i,j∈[0,|cells|): firstOccurrence(cells,𝔄[0],i)\n       ∧ firstOccurrence(cells,𝔄[|𝔄|-1],j) ∧ a=⌊minimumPair(i,j)⌋ ∧ b=⌊maximumPair(i,j)⌋)\n    ∨ (extent=\"first-x\" ∧ a=0 ∧ |cells|>0 ∧ 1<=D(cells[0])<=|cells| ∧ b=D(cells[0])-1))\n  ∧ ∀s∈[a,b-1): allDifferent(window(cells,3,s,false),λc:cell: classMod3(D(c)))\n\n```\n"},{"file":"rules/index-count.md","text":"---\nname: Index Count\nurl: https://rules.sudoku-sleuth.com/index-count.md\nkind: index-count\nalias_of: lookup\n---\n\n\n"},{"file":"rules/index-line.md","text":"---\nname: Index Line\nurl: https://rules.sudoku-sleuth.com/index-line.md\nkind: index-line\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required. No repeated cell; 2 ≤ n ≤ min(16,\\|𝔄\\|).\n    type: path<cell>\nalias_of: lookup\nalias_bind:\n  mode: '\"queries\"'\n  cells: orderedCells({})\n  cell: absent(boardCell(1,1))\n  sources: orderedCells({})\n  indexChannel: '\"D\"'\n  channel: '\"D\"'\n  offset: \"0\"\n  target: absent(0)\n  targetCell: absent(boardCell(1,1))\n  relation: relationSpec(\"difference\",0)\n  queries: ⟨lookupQuery(line,D(line[i]),i+1,\"D\",relationSpec(\"difference\",0)):i∈[0,|line|)⟩\n  total: \"|line|\"\n  firstMatch: \"false\"\n  reverseRelation: \"false\"\n  increasing: orderedCells({})\n  nonempty: \"false\"\nlayer: rule\n---\n\n\n"},{"file":"rules/index.md","text":"---\nname: Index\nurl: https://rules.sudoku-sleuth.com/index.md\nkind: index\nparameters:\n  axis:\n    description: \"The indexing direction: row or column.\"\n    default: Required.\n    type: enum{row,column}\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nalias_of: lookup\nalias_bind:\n  mode: '\"queries\"'\n  cells: orderedCells({})\n  cell: absent(boardCell(1,1))\n  sources: orderedCells({})\n  indexChannel: '\"D\"'\n  channel: '\"D\"'\n  offset: \"0\"\n  target: absent(0)\n  targetCell: absent(boardCell(1,1))\n  relation: relationSpec(\"difference\",0)\n  queries: ⟨lookupQuery(if axis=\"column\" then ⟨boardCell(row(c),k):k∈[0,cols)⟩ else ⟨boardCell(r,col(c)):r∈[0,rows)⟩,D(c),if axis=\"column\" then col(c)+1 else row(c)+1,\"D\",relationSpec(\"difference\",0)):c∈orderedCells(cells)⟩\n  total: \"|cells|\"\n  firstMatch: \"false\"\n  reverseRelation: \"false\"\n  increasing: orderedCells({})\n  nonempty: \"false\"\nlayer: rule\n---\n\n\n"},{"file":"rules/japanese-sums.md","text":"---\nname: Japanese Sums\nurl: https://rules.sudoku-sleuth.com/japanese-sums.md\nkind: japanese-sums\nshape: Outside\nparameters:\n  line:\n    type: list<cell>\n    description: Cells in clue order.\n    default: Required.\n  selectionRef:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: The selection name; H means board shading.\n    default: '\"H\".'\n  totals:\n    type: list<number>\n    description: One total per maximal marked run.\n    default: Required.\n  channel:\n    type: Channel\n    description: Read face digits D or effective values V.\n    default: D.\n  repeats:\n    type: boolean\n    description: Allow equal numbers within a run.\n    default: true.\nlayer: rule\n---\n\nClass: **existential**\n```text\n((allDifferent(line,λc:cell:cellIndex(c)) and (countWhere([0,|line|),λi:position:markedStart(line,i,selectionRef)) = |totals|)) and forall a∈[0,|line|): forall b∈[(a + 1),(|line| + 1)): (markedRun(line,a,b,selectionRef) implies let j=countWhere([0,a),λi:position:markedStart(line,i,selectionRef)); ((((0 <= j) and (j < |totals|)) and repeatPolicy(⟨line[i]:i∈[a,b)⟩,channel,repeats)) and (aggregate(⟨line[i]:i∈[a,b)⟩,channel,\"sum\") = totals[j]))))\n\n```\n"},{"file":"rules/killer.md","text":"---\nname: Killer Cage\nurl: https://rules.sudoku-sleuth.com/killer.md\nkind: killer\nalias_of: cage\n---\n\n\n"},{"file":"rules/kropki.md","text":"---\nname: Kropki\nurl: https://rules.sudoku-sleuth.com/kropki.md\nkind: kropki\naliases: [white dot, black dot, Kropki dots]\nparameters:\n  colour:\n    description: \"The relationship: white means difference 1; black means ratio 2.\"\n    default: '\"white\".'\n    type: enum{white,black}\n    syntax:\n      form: keywords\n      named: true\n      choices:\n        white: {}\n        black: {}\n  cells:\n    description: The two marked cells in order, for example r1c1-r1c2.\n    default: Empty list.\n    type: list<cell>\n    syntax:\n      form: cells\n      count: 2\n  white:\n    type: list<list<cell>>\n    description: Pairs marked white; each pair has exactly two cells.\n    default: Empty list.\n  black:\n    type: list<list<cell>>\n    description: Pairs marked black; each pair has exactly two cells.\n    default: Empty list.\n  allGiven:\n    type: list<enum{white,black}>\n    description: Kinds for which every possible orthogonal mark is given.\n    default: Empty list.\nalias_of: marked-pairs\nalias_bind:\n  x: '⟨cells:i∈[0,0)⟩'\n  v: '⟨cells:i∈[0,0)⟩'\n  white: 'if |cells|>0 ∧ colour=\"white\" then ⟨if i<|white| then white[i] else cells:i∈[0,|white|+1)⟩ else white'\n  black: 'if |cells|>0 ∧ colour=\"black\" then ⟨if i<|black| then black[i] else cells:i∈[0,|black|+1)⟩ else black'\n  allGiven: allGiven\nlayer: rule\n---\n\n\n"},{"file":"rules/layered-cage.md","text":"---\nname: Layered Cage\nurl: https://rules.sudoku-sleuth.com/layered-cage.md\nkind: layered-cage\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  upper:\n    description: The digits treated as the upper layer.\n    default: Required.\n    type: set<digit>\nlayer: rule\n---\n\nClass: **first-order**\n```text\n∀a,b ∈ cells:\n  (row(a)=row(b) → ((D(a)∈upper) ↔ (D(b)∈upper)))\n  ∧ (D(a)∈upper ∧ D(b)∉upper → row(a)<row(b))\n\n```\n"},{"file":"rules/liar-cells.md","text":"---\nname: Liar Cells\nurl: https://rules.sudoku-sleuth.com/liar-cells.md\nkind: liar-cells\nshape: Cells\nlayer: rule\nparameters:\n  groups:\n    type: list<set<cell>>\n    description: The groups in which to count liar cells.\n    default: The 27 standard rows, columns and 3x3 boxes on a 9x9 board; otherwise required.\n  count:\n    type: position\n    description: The exact number of liar cells in each group.\n    default: 1.\n  values:\n    type: list<number>\n    description: The allowed real values of liar cells.\n    default: The integers 1 through 9 on a 9x9 board; otherwise required.\n  distinctDigits:\n    type: boolean\n    description: Whether all liar cells have different face digits.\n    default: true.\n  distinctValues:\n    type: boolean\n    description: Whether all liar cells have different real values.\n    default: true.\n---\n\nClass: **existential**\n```text\n∃M:set<cell>: M⊆C\n∧ (∀G∈groups: |G∩M|=count)\n∧ (distinctDigits → allDifferent(M,λc:cell:D(c)))\n∧ (distinctValues → allDifferent(M,λc:cell:V(c)))\n∧ (∀c∈C: (c∈M → (V(c)∈values ∧ V(c)!=D(c))) ∧ (c∉M → V(c)=D(c)))\n∧ (∀meaning∈ValuedRuleMeanings: meaning)\n\n```\n"},{"file":"rules/limited-digits.md","text":"---\nname: Limited Digits\nurl: https://rules.sudoku-sleuth.com/limited-digits.md\nkind: limited-digits\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  max:\n    description: The greatest number of listed rules or different digits allowed.\n    default: Required.\n    type: number\nalias_of: digit-profile\nalias_bind:\n  cells: line\n  classes: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  counts: ⟨i:i∈[0,0)⟩\n  channel: '\"D\"'\n  loop: \"false\"\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  exhaustive: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: some(max)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/line-choice.md","text":"---\nname: Line Choice\nurl: https://rules.sudoku-sleuth.com/line-choice.md\nkind: line-choice\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  kinds:\n    description: The line rules available to choose from.\n    default: Required.\n    type: list<enum{renban,nabner,modular,entropic,parity}>\n  min:\n    description: The least number of listed rules that must hold.\n    default: Required.\n    type: number\n  max:\n    description: The greatest number of listed rules or different digits allowed.\n    default: Required.\n    type: number\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nlayer: block\ncomposition: Compose arbitrary line-rule alternatives with cardinality bounds.\n---\n\nClass: **with aggregates**\n```text\nlineGeometry(line,edges,loop) ∧ let S=if present(edges) then allCells(unwrap(edges)) else {c∈C:c∈line};\nlet selected=λoption:enum{renban,nabner,modular,entropic,parity}:\n  (option=\"renban\" ∧ (if present(edges) then valueSet(S,\"D\",false,\"consecutive\") else valueSet(line,\"D\",false,\"consecutive\")))\n  ∨ (option=\"nabner\" ∧ (if present(edges) then valueSet(S,\"D\",true,if false then \"separated\" else \"nonconsecutive\") else valueSet(line,\"D\",true,if false then \"separated\" else \"nonconsecutive\")))\n  ∨ (option=\"modular\" ∧ (if present(edges) then modularMeaning(line,edges,loop,3,3) else ∀W∈lineWindows(line,edges,3,loop): allDifferent(W,λc:cell:classMod3(D(c)))))\n  ∨ (option=\"entropic\" ∧ (if present(edges) then entropicMeaning(line,edges,loop) else |𝔄|>0 ∧ |𝔄| mod 3=0 ∧ ∀W∈lineWindows(line,edges,3,loop): allDifferent(W,λc:cell:classEntropy(D(c)))))\n  ∨ (option=\"parity\" ∧ parityMeaning(line,edges,loop));\nmin<=countWhere(kinds,selected)<=max\n\n```\n"},{"file":"rules/little-killer.md","text":"---\nname: Little Killer\nurl: https://rules.sudoku-sleuth.com/little-killer.md\nkind: little-killer\nalias_of: diagonal-sum\n---\n\n\n"},{"file":"rules/local-sequence.md","text":"---\nname: Local Sequence\nurl: https://rules.sudoku-sleuth.com/local-sequence.md\nkind: local-sequence\nshape: Lines\nparameters:\n  line:\n    type: path<cell>\n    description: The ordered cells.\n    default: Required.\n  mode:\n    type: enum{transitions,divisors,recurrence}\n    description: Allowed directed pairs, successive divisibility, or a two-term linear recurrence.\n    default: Required.\n  allowed:\n    type: list<list<number>>\n    description: Allowed ordered number pairs.\n    default: Empty list.\n  a:\n    type: number\n    description: Coefficient of the earlier recurrence term.\n    default: \"1.\"\n  b:\n    type: number\n    description: Coefficient of the later recurrence term.\n    default: \"1.\"\n  loop:\n    type: boolean\n    description: Include the closing transition; recurrence uses an open line.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: block\ncomposition: Explicit transition tables, divisibility and linear recurrences.\n---\n\nClass: **first-order**\n```text\n(((((|line| > 0) and (loop implies (|line| >= 3))) and ((mode = \"recurrence\") implies not(loop))) and ((mode = \"transitions\") implies forall p∈allowed: (|p| = 2))) and if (mode = \"recurrence\") then forall i∈[0,(|line| - 2)): (read(line[(i + 2)],channel) = ((a * read(line[i],channel)) + (b * read(line[(i + 1)],channel)))) else forall i,j∈[0,|line|): (next(line,i,j,loop) implies if (mode = \"divisors\") then divides(read(line[i],channel),read(line[j],channel)) else transitionAllowed(read(line[i],channel),read(line[j],channel),allowed)))\n\n```\n"},{"file":"rules/lockout.md","text":"---\nname: Lockout\nurl: https://rules.sudoku-sleuth.com/lockout.md\nkind: lockout\nparameters:\n  ends:\n    description: The two end cells, in their stated order.\n    default: Required.\n    type: list<cell>\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  gap:\n    description: The least difference between the two end digits.\n    default: Required.\n    type: number\nlayer: rule\nalias_of: endpoint-range\nalias_bind:\n  ends: ends\n  line: line\n  outside: \"true\"\n  gap: gap\n---\n\n\n"},{"file":"rules/look-and-say.md","text":"---\nname: Look And Say\nurl: https://rules.sudoku-sleuth.com/look-and-say.md\nkind: look-and-say\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  counts:\n    type: list<record{digit:digit,count:position}>\n    description: Each digit and the exact number of times it must appear.\n    default: Required.\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨p.digit:i∈[0,1)⟩:p∈counts⟩\n  counts: ⟨p.count:p∈counts⟩\n  exhaustive: \"false\"\n  channel: '\"D\"'\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/lookup.md","text":"---\nname: Lookup\nurl: https://rules.sudoku-sleuth.com/lookup.md\nkind: lookup\nshape: Cells\nparameters:\n  mode:\n    type: enum{single,count,queries}\n    description: One dynamic source, a list of dynamic sources, or explicit queries.\n    default: single.\n  cells:\n    type: list<cell>\n    description: The cells in lookup order, starting at position one.\n    default: Empty list.\n  cell:\n    type: optional<cell>\n    description: The cell whose number gives the lookup position.\n    default: Absent; required in single mode.\n  indexChannel:\n    type: Channel\n    description: The channel supplying the position.\n    default: D.\n  channel:\n    type: Channel\n    description: The channel supplying the looked-up and target numbers.\n    default: D.\n  offset:\n    type: position\n    description: Add this offset to the index number before looking up the position.\n    default: 0\n  target:\n    type: optional<number>\n    description: A fixed comparison target, taking precedence over targetCell.\n    default: Absent; use targetCell or the index cell.\n  targetCell:\n    type: optional<cell>\n    description: The cell supplying the comparison target.\n    default: Absent; use the index cell.\n  relation:\n    type: PairRelation\n    description: The relation from the looked-up number to the target number.\n    default: difference 0 (equal).\n  sources:\n    type: list<cell>\n    description: Source occurrences in count mode.\n    default: Empty list.\n  queries:\n    type: list<LookupQuery>\n    description: Ordered lookups, each with its own cells, one-based index, target, channel and relation.\n    default: Empty list.\n  total:\n    type: position\n    description: Required number of successful queries.\n    default: \"1.\"\n  firstMatch:\n    type: boolean\n    description: Exclude earlier matching targets in each query.\n    default: false.\n  increasing:\n    type: list<cell>\n    description: A source path required to increase in printed digits.\n    default: Empty list.\n  reverseRelation:\n    type: boolean\n    description: Compare the query target with the looked-up value.\n    default: false.\n  nonempty:\n    type: boolean\n    description: Require an increasing source path to be nonempty.\n    default: false.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\n(mode=\"single\" → present(cell)) ∧ let activeQueries=if mode=\"queries\" then queries else ⟨lookupQuery(cells,read(s,indexChannel)+offset,if present(target) then unwrap(target) else if present(targetCell) then read(unwrap(targetCell),channel) else read(s,channel),channel,relation):s∈(if mode=\"single\" then ⟨unwrap(cell):i∈[0,1),present(cell)⟩ else sources)⟩; (nonempty → |increasing|>0) ∧ (∀i∈[0,|increasing|-1): D(increasing[i])<D(increasing[i+1])) ∧ total=countWhere(activeQueries,λq:LookupQuery:(if reverseRelation then ⌊q.index⌋=q.index ∧ (∃k∈[1,|q.cells|+1): k=q.index ∧ pairRelation(q.relation,q.target,read(lookup(q.cells,k),q.channel))) else queryHit(q)) ∧ (firstMatch → ∀i∈[0,|q.cells|): i<q.index-1 → ¬pairRelation(q.relation,read(q.cells[i],q.channel),q.target)))\n\n```\n"},{"file":"rules/magic-square.md","text":"---\nname: Magic Square\nurl: https://rules.sudoku-sleuth.com/magic-square.md\nkind: magic-square\nparameters:\n  places:\n    description: The nine cells of each candidate magic square, in row order.\n    default: Required.\n    type: list<list<cell>>\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n∃P∈places: |P|=9 ∧ allDifferent(P,λoccurrence:cell: D(occurrence)) ∧ (∀c∈P: D(c)∈[1,10)) ∧ (∀T∈magicLines(P): aggregate(T,\"D\",\"sum\")=15)\n\n```\n"},{"file":"rules/mapped-values.md","text":"---\nname: Mapped Values\nurl: https://rules.sudoku-sleuth.com/mapped-values.md\nkind: mapped-values\nshape: Global\nparameters:\n  selectionRef:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: Selection name; H means board shading.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Cells where the selected transformation applies.\n    default: Required.\n  values:\n    shared:\n      role: conjoin\n      type: value\n    type: string\n    description: Output channel; V or an independent name.\n    default: '\"V\".'\n  mode:\n    type: enum{affine,map,free}\n    description: Transformation of selected digits.\n    default: affine.\n  factor:\n    type: number\n    description: Affine multiplier.\n    default: \"1.\"\n  offset:\n    type: number\n    description: Affine offset.\n    default: \"0.\"\n  mapping:\n    type: list<ValueMap>\n    description: Explicit digit and value records.\n    default: Empty list.\n  allowed:\n    type: list<number>\n    description: Allowed selected values in free mode.\n    default: Empty list.\n  different:\n    type: boolean\n    description: Require selected values to differ from face digits.\n    default: false.\n  outside:\n    type: enum{identity,free}\n    description: Policy for cells outside scope.\n    default: free.\nlayer: block\ncomposition: Compose numeric channels with shared selections.\n---\n\nClass: **existential**\n```text\nvalues!=\"D\" ∧ validValueMap(mapping) ∧ ∀c∈C: let v=channelValue(values,c); if c∈scope then (if marked(selectionRef,c) then (if mode=\"affine\" then v=affineValue(c,factor,offset) else if mode=\"map\" then mappedValue(D(c),v,mapping) else v∈allowed) ∧ (different → v!=D(c)) else v=D(c)) else (outside=\"identity\" → v=D(c))\n\n```\n"},{"file":"rules/marked-pairs.md","text":"---\nname: Marked Pairs\nurl: https://rules.sudoku-sleuth.com/marked-pairs.md\nkind: marked-pairs\nshape: Edges\nparameters:\n  x:\n    type: list<list<cell>>\n    description: Pairs marked x; each pair has exactly two cells.\n    default: Empty list.\n  v:\n    type: list<list<cell>>\n    description: Pairs marked v; each pair has exactly two cells.\n    default: Empty list.\n  white:\n    type: list<list<cell>>\n    description: Pairs marked white; each pair has exactly two cells.\n    default: Empty list.\n  black:\n    type: list<list<cell>>\n    description: Pairs marked black; each pair has exactly two cells.\n    default: Empty list.\n  allGiven:\n    type: list<enum{x,v,white,black}>\n    description: Kinds for which every possible orthogonal mark is given.\n    default: Empty list.\nlayer: block\n---\n\nClass: **first-order**\n```text\n(∀p∈x: |p|=2 ∧ pairRelation(relationSpec(\"sum\",10),V(p[0]),V(p[1]))) ∧\n(\"x\"∈allGiven → (∀a,b∈C: moveRelation(\"orthogonal\",a,b) ∧ ¬graphEdge(x,a,b) → ¬pairRelation(relationSpec(\"sum\",10),D(a),D(b)))) ∧\n(∀p∈v: |p|=2 ∧ pairRelation(relationSpec(\"sum\",5),V(p[0]),V(p[1]))) ∧\n(\"v\"∈allGiven → (∀a,b∈C: moveRelation(\"orthogonal\",a,b) ∧ ¬graphEdge(v,a,b) → ¬pairRelation(relationSpec(\"sum\",5),D(a),D(b)))) ∧\n(∀p∈white: |p|=2 ∧ pairRelation(relationSpec(\"difference\",1),V(p[0]),V(p[1]))) ∧\n(\"white\"∈allGiven → (∀a,b∈C: moveRelation(\"orthogonal\",a,b) ∧ ¬graphEdge(white,a,b) → ¬pairRelation(relationSpec(\"difference\",1),D(a),D(b)))) ∧\n(∀p∈black: |p|=2 ∧ pairRelation(relationSpec(\"ratio\",2),V(p[0]),V(p[1]))) ∧\n(\"black\"∈allGiven → (∀a,b∈C: moveRelation(\"orthogonal\",a,b) ∧ ¬graphEdge(black,a,b) → ¬pairRelation(relationSpec(\"ratio\",2),D(a),D(b))))\n\n```\n"},{"file":"rules/marking-relation.md","text":"---\nname: Marking Relation\nurl: https://rules.sudoku-sleuth.com/marking-relation.md\nkind: marking-relation\nshape: Edges\nparameters:\n  selectionRef:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: The shared selection name; H means board shading.\n    default: Required.\n  pairs:\n    type: list<list<cell>>\n    description: Ordered cell pairs.\n    default: Empty list.\n  relation:\n    type: enum{same,different,\"implies\"}\n    description: Relationship between pair marks.\n    default: different.\n  line:\n    type: list<cell>\n    description: Occurrences along which to count mark changes.\n    default: Empty list.\n  transitions:\n    type: optional<position>\n    description: Required number of changes.\n    default: Absent; no count condition.\nlayer: block\ncomposition: Relations over arbitrary shared cell markings.\n---\n\nClass: **existential**\n```text\n(∀p∈pairs: |p|=2 ∧ markingRelation(p[0],p[1],selectionRef,relation)) ∧ (present(transitions) → countWhere([0,|line|-1),λi:position:0<=i ∧ i<|line| ∧ 0<=i+1 ∧ i+1<|line| ∧ ¬(marked(selectionRef,line[i]) ↔ marked(selectionRef,line[i+1])))=unwrap(transitions))\n\n```\n"},{"file":"rules/maze.md","text":"---\nname: Maze\nurl: https://rules.sudoku-sleuth.com/maze.md\nkind: maze\nshape: Lines\nparameters:\n  name:\n    shared:\n      role: construct\n      type: network\n    type: string\n    description: The shared network name.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: The exact nonempty vertex set.\n    default: Required.\n  move:\n    type: Move\n    description: Allowed edge geometry.\n    default: orthogonal.\n  tree:\n    type: boolean\n    description: Require a connected acyclic network.\n    default: true.\n  requiredEdges:\n    type: list<list<cell>>\n    description: Undirected edges that must be present.\n    default: Empty list.\n  forbiddenEdges:\n    type: list<list<cell>>\n    description: Undirected edges that must be absent.\n    default: Empty list.\n  leaves:\n    type: optional<set<cell>>\n    description: The exact cells with degree one.\n    default: Absent; no leaf condition.\n  maximumDegree:\n    type: optional<position>\n    description: Maximum number of incident edges per vertex.\n    default: Absent; no degree bound.\nlayer: block\ncomposition: Named network construction with configurable topology.\n---\n\nClass: **existential**\n```text\nlet E=networkAnswer(name); networkOn(E,scope,move) ∧ (tree → |E|=|scope|-1) ∧ (∀e∈requiredEdges: |e|=2 ∧ graphEdge(E,e[0],e[1])) ∧ (∀e∈forbiddenEdges: |e|=2 ∧ ¬graphEdge(E,e[0],e[1])) ∧ (present(leaves) → {c∈scope:networkDegree(E,c)=1}=unwrap(leaves)) ∧ (present(maximumDegree) → ∀c∈scope:networkDegree(E,c)<=unwrap(maximumDegree))\n\n```\n"},{"file":"rules/mean-lines.md","text":"---\nname: Mean Lines\nurl: https://rules.sudoku-sleuth.com/mean-lines.md\nkind: mean-lines\nparameters:\n  lines:\n    description: The cells in each line, in order.\n    default: Required.\n    type: list<list<cell>>\nalias_of: aggregate-groups\nalias_bind:\n  groups: lines\n  operation: '\"mean\"'\n  channel: '\"D\"'\n  repeats: \"true\"\n  line: absent(orderedCells(C))\n  combine: \"false\"\nlayer: rule\n---\n\n\n"},{"file":"rules/mirrored-pairs.md","text":"---\nname: Mirrored Pairs\nurl: https://rules.sudoku-sleuth.com/mirrored-pairs.md\nkind: mirrored-pairs\nlayer: block\nparameters:\n  line:\n    type: list<cell>\n    description: The ordered line.\n    default: Empty list.\n  geometry:\n    type: enum{line,rotation}\n    description: Pair line positions or board cells.\n    default: line.\n  mode:\n    type: enum{equal,\"equal-sum\",\"allowed-sum\"}\n    description: Compare paired values or their sums.\n    default: equal.\n  channel:\n    type: Channel\n    description: Read digits D or effective values V.\n    default: D.\n  sums:\n    type: list<number>\n    description: Allowed pair sums.\n    default: Empty list.\n  centre:\n    type: enum{\"when-odd\",ignore,required}\n    description: How a line centre constrains common sums.\n    default: ignore.\n---\n\nClass: **first-order**\n```text\n(geometry=\"rotation\" → ∀c∈C: if mode=\"equal\" then read(c,channel)=read(turn(c),channel) else read(c,channel)+read(turn(c),channel)∈sums)\n∧ (geometry=\"line\" → (if mode=\"equal\" then ∀i∈[0,|line|): read(line[i],channel)=read(line[mirror(line,i)],channel) else (∀i,j∈[0,|line|): i<⌊|line|/2⌋ ∧ j<⌊|line|/2⌋ → (if mode=\"equal-sum\" then read(line[i],channel)+read(line[|line|-1-i],channel)=read(line[j],channel)+read(line[|line|-1-j],channel) else read(line[i],channel)+read(line[|line|-1-i],channel)∈sums)) ∧ (centre=\"required\" → |line| mod 2=1) ∧ (centre!=\"ignore\" ∧ |line| mod 2=1 → ∀i∈[0,|line|): i<⌊|line|/2⌋ → |line|>0 ∧ 0<=⌊|line|/2⌋<|line| ∧ read(line[i],channel)+read(line[|line|-1-i],channel)=read(line[⌊|line|/2⌋],channel))))\n\n```\n"},{"file":"rules/modular.md","text":"---\nname: Modular\nurl: https://rules.sudoku-sleuth.com/modular.md\nkind: modular\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  modulus:\n    description: The divisor used to take remainders.\n    default: 3; modulus ≥ 1.\n    type: position\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  length:\n    type: position\n    description: The number of consecutive cells in each window, independent of the modulus.\n    default: 3; length ≥ 2.\nalias_of: class-pattern\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  classification: '\"residue\"'\n  modulus: modulus\n  length: length\n  geometry: '\"line\"'\n  mode: '\"distinct\"'\n  fixedClass: absent(|{}|)\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/molecules.md","text":"---\nname: Molecules\nurl: https://rules.sudoku-sleuth.com/molecules.md\nkind: molecules\nparameters:\n  atoms:\n    description: The electron cells touching each atom, one list per atom.\n    default: Required.\n    type: list<set<cell>>\n  sum:\n    description: The total the digits or values must add up to.\n    default: Required.\n    type: number\n  electronMax:\n    description: Every digit at or below this number must be an electron.\n    default: Required.\n    type: digit\nlayer: rule\n---\n\nClass: **existential**\n```text\n∃E:set<cell>: E⊆allCells(atoms)\n  ∧ (∀c∈allCells(atoms): D(c)<=electronMax → c∈E)\n  ∧ (∀A∈atoms: aggregate(A∩E,\"D\",\"sum\")=sum)\n\n```\n"},{"file":"rules/monotone-line.md","text":"---\nname: Monotone Line\nurl: https://rules.sudoku-sleuth.com/monotone-line.md\nkind: monotone-line\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  strict:\n    type: boolean\n    description: Whether each step must strictly increase.\n    default: true.\n  orientation:\n    type: Orientation\n    description: Read forwards, backwards, or choose either direction for the whole line.\n    default: forward.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\nlayer: block\n---\n\nClass: **first-order**\n```text\n((((orientation = \"forward\") or (orientation = \"either\")) and forall i∈[0,(|line| - 1)): if strict then (read(line[i],channel) < read(line[(i + 1)],channel)) else (read(line[i],channel) <= read(line[(i + 1)],channel))) or (((orientation = \"reverse\") or (orientation = \"either\")) and forall i∈[0,(|line| - 1)): if strict then (read(line[i],channel) > read(line[(i + 1)],channel)) else (read(line[i],channel) >= read(line[(i + 1)],channel))))\n\n```\n"},{"file":"rules/n-mate.md","text":"---\nname: N Mate\nurl: https://rules.sudoku-sleuth.com/n-mate.md\nkind: n-mate\nparameters:\n  cell:\n    description: The clue cell.\n    default: Required.\n    type: cell\n  ray:\n    description: The cells along the ray, nearest first.\n    default: Required.\n    type: list<cell>\n  cage:\n    description: The cells in the cage.\n    default: Required.\n    type: set<cell>\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\nlet n=D(cell); 1<=n<=|ray| ∧ n+D(ray[n-1])=aggregate(cage,\"D\",\"sum\") ∧ repeatPolicy(cage,\"D\",false)\n\n```\n"},{"file":"rules/nabner.md","text":"---\nname: Nabner\nurl: https://rules.sudoku-sleuth.com/nabner.md\nkind: nabner\nparameters:\n  line:\n    empty_when: edges\n    type: list<cell>\n    description: All cells of the line or cell set; order does not affect comparisons.\n    default: Required.\n  distinct:\n    description: Whether repeated digits are forbidden.\n    default: false (repeats allowed).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  separated:\n    type: boolean\n    description: Require a difference greater than one instead of merely forbidding a difference of one.\n    default: false.\n  selection:\n    type: optional<PrefixSelection>\n    description: A prefix ending at the first target, given or listed crust; include chooses whether to keep that cell.\n    default: Absent; use the whole cell set or network.\nalias_of: value-set\nalias_bind:\n  line: line\n  edges: edges\n  selection: selection\n  channel: channel\n  repeats: ¬distinct\n  mode: if separated then \"separated\" else \"nonconsecutive\"\nlayer: rule\n---\n\n\n"},{"file":"rules/negative.md","text":"---\nname: Negative\nurl: https://rules.sudoku-sleuth.com/negative.md\nkind: negative\nparameters:\n  relations:\n    description: The relationships to forbid, each with its operation and any required value.\n    default: Required.\n    type: list<PairRelation>\n  except:\n    allow_empty: true\n    description: The cell pairs exempt from the negative rule.\n    default: Required.\n    type: list<list<cell>>\n  within:\n    description: Groups limiting the pairs covered by the rule.\n    default: Absent; no inferred value.\n    type: optional<list<set<cell>>>\n  direction:\n    description: The chosen diagonal or neighbour orientation, as named in the definition.\n    default: Absent; no inferred value.\n    type: optional<enum{horizontal,vertical}>\nalias_of: relation-scope\nalias_bind:\n  cells: C\n  relations: relations\n  mode: '\"moves\"'\n  move: '\"orthogonal\"'\n  anchors: \"{}\"\n  except: '{p∈cellLists(C,2): |p|=2 ∧ (graphEdge(except,p[0],p[1]) ∨ (present(within) ∧ ¬(∃G∈unwrap(within):p[0]∈G ∧ p[1]∈G)) ∨ (present(direction) ∧ ¬((unwrap(direction)=\"horizontal\" ∧ row(p[0])=row(p[1])) ∨ (unwrap(direction)=\"vertical\" ∧ col(p[0])=col(p[1])))))}'\n  negative: \"true\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/neighbour-count.md","text":"---\nname: Neighbour Count\nurl: https://rules.sudoku-sleuth.com/neighbour-count.md\nkind: neighbour-count\nshape: Cells\nparameters:\n  cell:\n    type: cell\n    description: The origin and first number in each comparison.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: The bounded neighbour scope.\n    default: Required.\n  move:\n    type: Move\n    description: Neighbour geometry.\n    default: orthogonal.\n  includeSelf:\n    type: boolean\n    description: Include the origin when it belongs to scope.\n    default: false.\n  relations:\n    type: list<PairRelation>\n    description: Inclusive alternatives from origin to neighbour.\n    default: Required.\n  total:\n    type: optional<position>\n    description: Fixed count; otherwise read the origin.\n    default: Absent; use the origin number.\n  exhaustive:\n    type: boolean\n    description: Require every neighbour to match.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: block\ncomposition: Counts of arbitrary neighbour relations.\n---\n\nClass: **with aggregates**\n```text\nlet S=selectedNeighbours(cell,scope,move,includeSelf); let n=countWhere(S,λd:cell:relatedAny(relations,read(cell,channel),read(d,channel))); n=(if present(total) then unwrap(total) else read(cell,channel)) ∧ (exhaustive → n=|S|)\n\n```\n"},{"file":"rules/neighbour-extremum.md","text":"---\nname: Neighbour Extremum\nurl: https://rules.sudoku-sleuth.com/neighbour-extremum.md\nkind: neighbour-extremum\nparameters:\n  type:\n    description: The mode named in the definition, such as min or max.\n    default: Required.\n    type: enum{min,max}\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  exhaustive:\n    description: Whether every occurrence is marked, so unmarked cells obey the opposite condition.\n    default: Required.\n    type: boolean\n  neighbourhood:\n    type: Move\n    description: The move defining neighbours.\n    default: orthogonal.\n  boundary:\n    type: boolean\n    description: Compare marked cells only with neighbours outside the marked set.\n    default: true.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  neighbours:\n    type: optional<set<cell>>\n    description: Explicit comparison neighbours, replacing move-selected neighbours.\n    default: Absent.\nlayer: block\n---\n\nClass: **first-order**\n```text\n(∀a∈cells: extremumAt(a,(if present(neighbours) then unwrap(neighbours) else {b∈C:moveRelation(neighbourhood,a,b) ∧ (¬boundary ∨ b∉cells)}),type,channel))\n∧ (exhaustive → ∀a∈C: a∉cells → ∃b∈C: moveRelation(neighbourhood,a,b) ∧ extremumAt(b,{a},type,channel))\n\n```\n"},{"file":"rules/network-clue.md","text":"---\nname: Network Clue\nurl: https://rules.sudoku-sleuth.com/network-clue.md\nkind: network-clue\nshape: Lines\nparameters:\n  network:\n    shared:\n      role: read\n      type: network\n    type: string\n    description: The shared network name.\n    default: Required.\n  route:\n    shared:\n      role: read\n      type: route\n    type: optional<string>\n    description: A shared open route whose steps must use the network.\n    default: Absent; no route condition.\n  relations:\n    type: list<PairRelation>\n    description: Inclusive alternatives on each undirected edge, ordered by board cell index.\n    default: Empty list; no numeric edge condition.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  degrees:\n    type: list<record{cell:cell,degree:position}>\n    description: Required incident-edge counts at marked vertices.\n    default: Empty list.\nlayer: block\ncomposition: Degree and edge constraints on shared networks.\n---\n\nClass: **existential**\n```text\nlet E=networkAnswer(network); (|relations|>0 → ∀a,b∈allCells(E): cellIndex(a)<cellIndex(b) ∧ graphEdge(E,a,b) → relatedAny(relations,read(a,channel),read(b,channel))) ∧ (∀d∈degrees: networkDegree(E,d.cell)=d.degree) ∧ (present(route) → let L=routeAnswer(unwrap(route)); |L|>0 ∧ ¬routeClosed(unwrap(route)) ∧ ∀i∈[0,|L|-1):graphEdge(E,L[i],L[i+1]))\n\n```\n"},{"file":"rules/number-property.md","text":"---\nname: Number Property\nurl: https://rules.sudoku-sleuth.com/number-property.md\nkind: number-property\nshape: Cages\nparameters:\n  operand:\n    type: AggregateOperand\n    description: The aggregate or ordered decimal operand.\n    default: Required.\n  property:\n    type: enum{prime,composite,power,divisible,places}\n    description: The numeric property to require.\n    default: Required.\n  argument:\n    type: position\n    description: Exponent, divisor or decimal digit count; unused for prime and composite.\n    default: \"2.\"\n  reverse:\n    type: boolean\n    description: Also accept the reverse decimal reading.\n    default: false.\n  remainder:\n    type: optional<number>\n    description: Require this remainder modulo argument instead of a numeric property.\n    default: Absent.\n  alternating:\n    type: boolean\n    description: Alternate the property and its complement over line windows.\n    default: false.\n  line:\n    type: list<cell>\n    description: Cells for alternating property checks.\n    default: Empty list.\n  edges:\n    type: optional<list<list<cell>>>\n    description: Optional connected network for alternation.\n    default: Absent.\n  loop:\n    type: boolean\n    description: Close an alternating path.\n    default: false.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nif alternating then lineGeometry(line,edges,loop) ∧ (∀c∈line:D(c)>1) ∧ (present(edges) → ∀c∈allCells(unwrap(edges)):D(c)>1) ∧ (∀W∈lineWindows(line,edges,2,loop): |W|=2 → ¬(numericProperty(D(W[0]),property,argument)↔numericProperty(D(W[1]),property,argument))) else operandValid(operand) ∧ (¬reverse ∨ operand.operation=\"decimal\") ∧ (if present(remainder) then argument>=1 ∧ ⌊aggregateExpression(operand)⌋=aggregateExpression(operand) ∧ rem(aggregateExpression(operand),argument)=unwrap(remainder) else (numericProperty(aggregateExpression(operand),property,argument) ∨ (reverse ∧ decimalValid(reversal(operandCells(operand))) ∧ numericProperty(decimal(reversal(operandCells(operand))),property,argument))))\n\n```\n"},{"file":"rules/numbered-room.md","text":"---\nname: Numbered Room\nurl: https://rules.sudoku-sleuth.com/numbered-room.md\nkind: numbered-room\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  digit:\n    description: The specified digit.\n    default: Required.\n    type: digit\nalias_of: lookup\nalias_bind:\n  mode: '\"queries\"'\n  cells: orderedCells({})\n  cell: absent(boardCell(1,1))\n  sources: orderedCells({})\n  indexChannel: '\"D\"'\n  channel: '\"D\"'\n  offset: \"0\"\n  target: absent(0)\n  targetCell: absent(boardCell(1,1))\n  relation: relationSpec(\"difference\",0)\n  queries: ⟨lookupQuery(cells,D(cells[i]),digit,\"D\",relationSpec(\"difference\",0)):i∈[0,|cells|),i=0⟩\n  total: \"1\"\n  firstMatch: \"false\"\n  reverseRelation: \"false\"\n  increasing: orderedCells({})\n  nonempty: \"false\"\nlayer: rule\n---\n\n\n"},{"file":"rules/odd-even-cells.md","text":"---\nname: Odd Even Cells\nurl: https://rules.sudoku-sleuth.com/odd-even-cells.md\nkind: odd-even-cells\naliases: [\"odd/even cells\", \"parity cells\", \"odd and even digits\"]\nparameters:\n  parity:\n    description: \"The required parity: odd or even.\"\n    default: Required.\n    type: enum{odd,even}\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nlayer: rule\nalias_of: class-pattern\nalias_bind:\n  line: orderedCells(cells)\n  edges: absent(⟨orderedCells(C):n∈[0,0)⟩)\n  loop: \"false\"\n  classification: '\"residue\"'\n  modulus: \"2\"\n  length: \"2\"\n  geometry: '\"cells\"'\n  mode: '\"same\"'\n  fixedClass: some(if parity=\"odd\" then |{0}| else |{}|)\n  channel: '\"V\"'\n---\n\n\n"},{"file":"rules/ordered-block.md","text":"---\nname: Ordered Block\nurl: https://rules.sudoku-sleuth.com/ordered-block.md\nkind: ordered-block\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  digits:\n    description: The allowed or required digits, listed explicitly; repeats in the list count where the rule says so.\n    default: Required.\n    type: list<digit>\nlayer: rule\n---\n\nClass: **first-order**\n```text\n∃p∈[0,|cells|-|digits|+1): ∀i∈[0,|digits|): D(cells[p+i])=digits[i]\n\n```\n"},{"file":"rules/outside.md","text":"---\nname: Outside\nurl: https://rules.sudoku-sleuth.com/outside.md\nkind: outside\nparameters:\n  cells:\n    type: collection<cell>\n    description: The marked cells. Lists retain repeated positions; sets contain each cell once.\n    default: Required.\n  digits:\n    description: The allowed or required digits, listed explicitly; repeats in the list count where the rule says so.\n    default: Required.\n    type: list<digit>\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨d:i∈[0,1)⟩:d∈digits⟩\n  counts: ⟨multiplicity(digits,d):d∈digits⟩\n  channel: '\"D\"'\n  loop: \"false\"\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  exhaustive: \"false\"\n  comparison: '\"at-least\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/pair.md","text":"---\nname: Pair\nurl: https://rules.sudoku-sleuth.com/pair.md\nkind: pair\nparameters:\n  relation:\n    description: The relationship keyword and any required whole-number value, for example difference 1.\n    default: Required.\n    type: PairRelation\n    syntax:\n      form: keywords\n      tag: op\n      choices:\n        difference:\n          value: integer\n        at-least:\n          value: integer\n        ratio:\n          value: integer\n        sum:\n          value: integer\n        less: {}\n        multiple: {}\n        shift: {}\n  cells:\n    description: The two marked cells in order, for example r1c1-r1c2.\n    default: Required.\n    type: list<cell>\n    syntax:\n      form: cells\n      count: 2\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨weightedOperand(aggregateOperand(⟨cells[i]:i∈[0,|cells|),i=0⟩,channel,\"sum\",true),1,1):termIndex∈[0,1)⟩\n  right: ⟨weightedOperand(aggregateOperand(⟨cells[i]:i∈[0,|cells|),i=1⟩,channel,\"sum\",true),1,1):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: if |cells|=2 then relation else relationSpec(\"difference\",-1)\nlayer: rule\n---\n\n\n"},{"file":"rules/paired-roles.md","text":"---\nname: Paired Roles\nurl: https://rules.sudoku-sleuth.com/paired-roles.md\nkind: paired-roles\nshape: Global\nparameters:\n  left:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: Left selection name.\n    default: Required.\n  right:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: Right selection name.\n    default: Required.\n  name:\n    shared:\n      role: construct\n      type: network\n    type: string\n    description: Shared network name containing undirected pairs.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Cells covered by the two roles.\n    default: Required.\n  relation:\n    type: PairRelation\n    description: Numeric relation from left to right.\n    default: Required.\n  channel:\n    type: Channel\n    description: Read face digits D or effective values V.\n    default: D.\nlayer: block\ncomposition: Bijections between shared cell roles.\n---\n\nClass: **existential**\n```text\nleft!=right ∧ let A=selectedCells(left); let B=selectedCells(right); let E=networkAnswer(name); A∪B=scope ∧ |A∩B|=0 ∧ canonicalEdges(E) ∧ (∀e∈E:|e|=2 ∧ ((e[0]∈A ∧ e[1]∈B) ∨ (e[1]∈A ∧ e[0]∈B))) ∧ (∀a∈A:∀b∈B:graphEdge(E,a,b) → pairRelation(relation,read(a,channel),read(b,channel))) ∧ (∀c∈scope:networkDegree(E,c)=1)\n\n```\n"},{"file":"rules/palindrome.md","text":"---\nname: Palindrome\nurl: https://rules.sudoku-sleuth.com/palindrome.md\nkind: palindrome\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\nlayer: rule\nalias_of: mirrored-pairs\nalias_bind:\n  line: line\n  geometry: '\"line\"'\n  mode: '\"equal\"'\n  channel: '\"V\"'\n  sums: ⟨n:n∈[0,0)⟩\n  centre: '\"ignore\"'\n---\n\n\n"},{"file":"rules/parity-cells.md","text":"---\nname: Parity Cells\nurl: https://rules.sudoku-sleuth.com/parity-cells.md\nkind: parity-cells\nalias_of: odd-even-cells\n---\n\n\n"},{"file":"rules/parity-line.md","text":"---\nname: Parity Line\nurl: https://rules.sudoku-sleuth.com/parity-line.md\nkind: parity-line\naliases: [\"Parity\"]\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: class-pattern\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  classification: '\"residue\"'\n  modulus: \"2\"\n  length: \"2\"\n  geometry: '\"line\"'\n  mode: '\"distinct\"'\n  fixedClass: absent(|{}|)\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/parity.md","text":"---\nname: Parity\nurl: https://rules.sudoku-sleuth.com/parity.md\nkind: parity\nalias_of: parity-line\n---\n\n\n"},{"file":"rules/pointing-arrow.md","text":"---\nname: Pointing Arrow\nurl: https://rules.sudoku-sleuth.com/pointing-arrow.md\nkind: pointing-arrow\nparameters:\n  cell:\n    description: The clue cell.\n    default: Required.\n    type: cell\n  ray:\n    description: The cells along the ray, nearest first.\n    default: Required.\n    type: list<cell>\n  target:\n    description: \"The target relationship: greater, less, source or first-five.\"\n    default: Required.\n    type: enum{greater,less,source,\"first-five\"}\n  source:\n    description: The cell whose digit the target must match.\n    default: Absent; source target requires it.\n    type: optional<cell>\nlayer: rule\nalias_of: lookup\nalias_bind:\n  mode: '\"queries\"'\n  cells: orderedCells({})\n  cell: absent(boardCell(1,1))\n  sources: orderedCells({})\n  indexChannel: '\"D\"'\n  channel: '\"D\"'\n  offset: \"0\"\n  target: absent(0)\n  targetCell: absent(boardCell(1,1))\n  relation: relationSpec(\"difference\",0)\n  queries: ⟨lookupQuery(ray,D(cell),if target=\"source\" ∧ present(source) then D(unwrap(source)) else if target=\"first-five\" then 5 else D(cell),\"D\",relationSpec(if target=\"less\" ∨ target=\"greater\" then \"less\" else \"difference\",0)):i∈[0,1),target!=\"source\" ∨ present(source)⟩\n  total: \"1\"\n  firstMatch: target=\"first-five\"\n  reverseRelation: target=\"greater\"\n  increasing: orderedCells({})\n  nonempty: \"false\"\n---\n\n\n"},{"file":"rules/pointing-thermo.md","text":"---\nname: Pointing Thermo\nurl: https://rules.sudoku-sleuth.com/pointing-thermo.md\nkind: pointing-thermo\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  ray:\n    description: The cells along the ray, nearest first.\n    default: Required.\n    type: list<cell>\nlayer: rule\nalias_of: lookup\nalias_bind:\n  mode: '\"queries\"'\n  cells: orderedCells({})\n  cell: absent(boardCell(1,1))\n  sources: orderedCells({})\n  indexChannel: '\"D\"'\n  channel: '\"D\"'\n  offset: \"0\"\n  target: absent(0)\n  targetCell: absent(boardCell(1,1))\n  relation: relationSpec(\"difference\",0)\n  queries: ⟨lookupQuery(ray,D(line[|line|-1]),D(line[0]),\"D\",relationSpec(\"difference\",0)):i∈[0,1),|line|>0⟩\n  total: \"1\"\n  firstMatch: \"false\"\n  reverseRelation: \"false\"\n  increasing: line\n  nonempty: \"true\"\n---\n\n\n"},{"file":"rules/prefix-sum.md","text":"---\nname: Prefix Sum\nurl: https://rules.sudoku-sleuth.com/prefix-sum.md\nkind: prefix-sum\nshape: Outside\nparameters:\n  cells:\n    type: list<cell>\n    description: The ordered ray from the clue.\n    default: Required.\n  stop:\n    type: enum{target,given,crust}\n    description: Stop at the first target number, supplied given, or listed crust digit.\n    default: Required.\n  target:\n    type: optional<number>\n    description: The target number; required for target mode.\n    default: Absent.\n  crusts:\n    type: list<digit>\n    description: The crust digits; the first encountered crust stops the prefix.\n    default: Empty list.\n  include:\n    type: boolean\n    description: Include the stopping cell in the total.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  total:\n    type: number\n    description: The required selected total.\n    default: Required.\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨weightedOperand(prefixOperand(cells,channel,stop,target,crusts,include),1,1):termIndex∈[0,1)⟩\n  right: ⟨weightedOperand(aggregateOperand(⟨c:c∈orderedCells(C),false⟩,\"D\",\"count\",true),total,0):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: relationSpec(\"difference\",0)\nlayer: rule\n---\n\n\n"},{"file":"rules/pressure-gauge.md","text":"---\nname: Pressure Gauge\nurl: https://rules.sudoku-sleuth.com/pressure-gauge.md\nkind: pressure-gauge\nparameters:\n  type:\n    description: Low counts larger neighbours; high counts smaller neighbours.\n    default: Required.\n    type: enum{low,high}\n  cell:\n    description: The clue cell.\n    default: Required.\n    type: cell\n  neighbours:\n    description: The cells counted or compared around the clue.\n    default: Required.\n    type: set<cell>\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n(type=\"low\" → countWhere(neighbours,λc:cell: D(c)>D(cell))=D(cell)) ∧ (type=\"high\" → countWhere(neighbours,λc:cell: D(c)<D(cell))=D(cell))\n\n```\n"},{"file":"rules/primality.md","text":"---\nname: Primality\nurl: https://rules.sudoku-sleuth.com/primality.md\nkind: primality\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: All edges of one connected network.\n    default: Absent; use the ordered line.\nlayer: rule\nalias_of: number-property\nalias_bind:\n  operand: aggregateOperand(orderedCells(line),\"D\",\"sum\",true)\n  property: '\"prime\"'\n  argument: \"2\"\n  reverse: \"false\"\n  remainder: absent(0)\n  alternating: \"true\"\n  line: line\n  edges: edges\n  loop: loop\n---\n\n\n"},{"file":"rules/product-cage.md","text":"---\nname: Product Cage\nurl: https://rules.sudoku-sleuth.com/product-cage.md\nkind: product-cage\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  product:\n    description: The total obtained by multiplying the digits.\n    default: Required.\n    type: number\n  distinct:\n    description: Whether repeated digits are forbidden.\n    default: Required.\n    type: boolean\nalias_of: aggregate-equation\nalias_bind:\n  left: ⟨weightedOperand(aggregateOperand(orderedCells(cells),\"D\",\"product\",¬distinct),1,1):termIndex∈[0,1)⟩\n  right: ⟨weightedOperand(aggregateOperand(⟨c:c∈orderedCells(C),false⟩,\"D\",\"count\",true),product,0):termIndex∈[0,1)⟩\n  leftOperation: '\"sum\"'\n  rightOperation: '\"sum\"'\n  relation: relationSpec(\"difference\",0)\nlayer: rule\n---\n\n\n"},{"file":"rules/profile-relation.md","text":"---\nname: Profile Relation\nurl: https://rules.sudoku-sleuth.com/profile-relation.md\nkind: profile-relation\nshape: Cages\nparameters:\n  left:\n    type: list<cell>\n    description: Left cell occurrences.\n    default: Required.\n  right:\n    type: list<cell>\n    description: Right cell occurrences.\n    default: Required.\n  multiset:\n    type: boolean\n    description: Compare multiplicities as well as membership.\n    default: true.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: block\ncomposition: Compare arbitrary numeric sets or multisets.\n---\n\nClass: **with aggregates**\n```text\nforall n∈({read(c,channel):c∈left} union {read(c,channel):c∈right}): if multiset then (classCount(left,{n},channel) = classCount(right,{n},channel)) else ((classCount(left,{n},channel) > 0) iff (classCount(right,{n},channel) > 0))\n\n```\n"},{"file":"rules/quadruple.md","text":"---\nname: Quadruple\nurl: https://rules.sudoku-sleuth.com/quadruple.md\nkind: quadruple\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  digits:\n    description: The allowed or required digits, listed explicitly; repeats in the list count where the rule says so.\n    default: Required.\n    type: list<digit>\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells({c∈cells:true})\n  classes: ⟨⟨d:i∈[0,1)⟩:d∈digits⟩\n  counts: ⟨multiplicity(digits,d):d∈digits⟩\n  channel: '\"D\"'\n  loop: \"false\"\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  exhaustive: \"false\"\n  comparison: '\"at-least\"'\n  maximumDistinct: absent(|{}|)\n  repeats: \"true\"\n  balancePairs: ⟨⟨n:n∈[0,0)⟩:i∈[0,0)⟩\n  sumFree: absent(|{}|)\nlayer: rule\n---\n\n\n"},{"file":"rules/region-clue.md","text":"---\nname: Region Clue\nurl: https://rules.sudoku-sleuth.com/region-clue.md\nkind: region-clue\nshape: Regions\nparameters:\n  partitionRef:\n    shared:\n      role: read\n      type: partition\n    type: string\n    description: The shared region collection name.\n    default: Required.\n  markers:\n    type: list<cell>\n    description: Cells whose containing region is constrained.\n    default: Required.\n  operation:\n    type: enum{sum,product,count}\n    description: Aggregate over each containing region.\n    default: sum.\n  target:\n    type: optional<number>\n    description: Fixed aggregate target.\n    default: Absent; read the marker number.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  perRegion:\n    type: optional<position>\n    description: Require this many marker occurrences in every region.\n    default: Absent; no marker count condition.\n  rays:\n    type: list<record{cells:list<cell>,total:position}>\n    description: Ordered rays and their required count of changes between regions.\n    default: Empty list.\nlayer: block\ncomposition: Aggregate clues over shared constructed regions.\n---\n\nClass: **existential**\n```text\nlet P=partitionAnswer(partitionRef); |P|>0 ∧ (∀m∈markers: ∃R∈P: m∈R ∧ aggregate(R,channel,operation)=(if present(target) then unwrap(target) else read(m,channel))) ∧ (present(perRegion) → ∀R∈P:countWhere(markers,λm:cell:m∈R)=unwrap(perRegion)) ∧ (∀g∈rays: (∀c∈g.cells:∃R∈P:c∈R) ∧ g.total=(count i∈[0,|g.cells|-1): ¬samePartition(P,g.cells[i],g.cells[i+1])))\n\n```\n"},{"file":"rules/region-partition.md","text":"---\nname: Region Partition\nurl: https://rules.sudoku-sleuth.com/region-partition.md\nkind: region-partition\nshape: Regions\nparameters:\n  name:\n    shared:\n      role: construct\n      type: partition\n    type: string\n    description: The shared region collection name.\n    default: '\"\". Choose a local partition.'\n  scope:\n    type: set<cell>\n    description: Cells covered exactly once.\n    default: Required.\n  sizes:\n    type: list<position>\n    description: Allowed region sizes.\n    default: Empty list; any positive size.\n  count:\n    type: optional<position>\n    description: Required number of regions.\n    default: Absent; no count condition.\n  distinct:\n    type: boolean\n    description: Require different numbers in each region.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  joins:\n    type: list<list<cell>>\n    description: Cell pairs required to share a region.\n    default: Empty list.\n  borders:\n    type: list<list<cell>>\n    description: Cell pairs required to occupy different regions.\n    default: Empty list.\n  separation:\n    type: optional<Move>\n    description: Forbid this move between different regions.\n    default: Absent; regions may touch.\nlayer: block\ncomposition: Named connected partitions with sizes, joins and borders.\n---\n\nClass: **existential**\n```text\nif name=\"\" then ∃P:set<set<cell>>: partitionMeaning(P,scope,sizes,count,distinct,channel,joins,borders,separation) else partitionMeaning(partitionAnswer(name),scope,sizes,count,distinct,channel,joins,borders,separation)\n\n```\n"},{"file":"rules/region-shape.md","text":"---\nname: Region Shape\nurl: https://rules.sudoku-sleuth.com/region-shape.md\nkind: region-shape\nshape: Regions\nparameters:\n  partitionRef:\n    shared:\n      role: read\n      type: partition\n    type: string\n    description: The shared region collection name.\n    default: Required.\n  shapes:\n    type: list<set<cell>>\n    description: Allowed template shapes.\n    default: Empty list; no template condition.\n  rotations:\n    type: boolean\n    description: Allow quarter-turn rotations of templates.\n    default: true.\n  reflections:\n    type: boolean\n    description: Allow reflected templates.\n    default: true.\n  uses:\n    type: optional<list<position>>\n    description: Exact number of regions congruent to each template, in order.\n    default: Absent; templates may be reused.\n  centres:\n    type: optional<list<RegionCentre>>\n    description: Doubled zero-based galaxy centre coordinates.\n    default: Absent; no symmetry condition.\nlayer: block\ncomposition: Shape templates and symmetries over shared regions.\n---\n\nClass: **existential**\n```text\nlet P=partitionAnswer(partitionRef); |P|>0 ∧ (|shapes|>0 → ∀R∈P: ∃S∈shapes:congruent(S,R,rotations,reflections)) ∧ (present(uses) → |shapes|=|unwrap(uses)| ∧ ∀i∈[0,|shapes|): 0<=i ∧ i<|unwrap(uses)| ∧ countWhere(P,λR:set<cell>:congruent(shapes[i],R,rotations,reflections))=unwrap(uses)[i]) ∧ (present(centres) → (∀i,j∈[0,|unwrap(centres)|): i!=j → (unwrap(centres)[i].row2!=unwrap(centres)[j].row2 ∨ unwrap(centres)[i].col2!=unwrap(centres)[j].col2)) ∧ (∀R∈P: countWhere(unwrap(centres),λg:RegionCentre:centreInside(R,g))=1 ∧ ∀g∈unwrap(centres):centreInside(R,g) → symmetricRegion(R,g.row2,g.col2)) ∧ (∀g∈unwrap(centres):∃R∈P:centreInside(R,g)))\n\n```\n"},{"file":"rules/region-sum.md","text":"---\nname: Region Sum\nurl: https://rules.sudoku-sleuth.com/region-sum.md\nkind: region-sum\nparameters:\n  combine:\n    description: Whether separate visits to the same region contribute to one regional total.\n    default: false (each visit is summed separately).\n    type: boolean\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  segments:\n    description: The cells in each segment, listed in path order.\n    default: Required.\n    type: list<list<cell>>\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\nlayer: rule\nalias_of: aggregate-groups\nalias_bind:\n  groups: segments\n  operation: '\"sum\"'\n  channel: channel\n  repeats: \"true\"\n  line: some(line)\n  combine: combine\n---\n\n\n"},{"file":"rules/regions.md","text":"---\nname: Regions\nurl: https://rules.sudoku-sleuth.com/regions.md\nkind: regions\naliases: [\"regions\", \"boxes\", \"irregular regions\", \"extra regions\", \"disjoint\", \"disjoint groups\"]\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nalias_of: relation-scope\nalias_bind:\n  cells: cells\n  relations: ⟨relationSpec(\"difference\",0):i∈[0,1)⟩\n  mode: '\"all\"'\n  move: '\"orthogonal\"'\n  anchors: \"{}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"true\"\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/relation-scope.md","text":"---\nname: Relation Scope\nurl: https://rules.sudoku-sleuth.com/relation-scope.md\nkind: relation-scope\nshape: Global\nparameters:\n  cells:\n    type: set<cell>\n    description: The bounded cell scope.\n    default: Required.\n  relations:\n    type: list<PairRelation>\n    description: Inclusive alternatives for each selected pair.\n    default: Required.\n  mode:\n    type: enum{all,moves,incident}\n    description: Select all pairs, move neighbours, or move neighbours incident to anchors.\n    default: moves.\n  move:\n    type: Move\n    description: The neighbour move.\n    default: orthogonal.\n  anchors:\n    type: set<cell>\n    description: Cells incident to covered edges.\n    default: Empty set.\n  except:\n    type: collection<list<cell>>\n    description: Undirected pairs exempt from the condition.\n    default: Empty list.\n  negative:\n    type: boolean\n    description: Forbid every alternative on selected pairs.\n    default: false.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: block\n---\n\nClass: **first-order**\n```text\n(∀p∈except: |p|=2) ∧ ∀a,b∈cells: cellIndex(a)<cellIndex(b) ∧ selectedPair(a,b,cells,mode,move,anchors) ∧ ¬graphEdge(except,a,b) → (if negative then ¬relatedAny(relations,read(a,channel),read(b,channel)) else relatedAny(relations,read(a,channel),read(b,channel)))\n\n```\n"},{"file":"rules/remainder-cage.md","text":"---\nname: Remainder Cage\nurl: https://rules.sudoku-sleuth.com/remainder-cage.md\nkind: remainder-cage\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  modulus:\n    description: The divisor used to take remainders.\n    default: Required. modulus ≥ 1.\n    type: position\n  remainder:\n    description: The remainder required after division by the modulus.\n    default: Required.\n    type: position\n  distinct:\n    description: Whether repeated digits are forbidden.\n    default: Required.\n    type: boolean\nlayer: rule\nalias_of: number-property\nalias_bind:\n  operand: aggregateOperand(orderedCells(cells),\"D\",\"sum\",¬distinct)\n  property: '\"divisible\"'\n  argument: modulus\n  reverse: \"false\"\n  remainder: some(remainder)\n  alternating: \"false\"\n  line: orderedCells({})\n  edges: absent(⟨orderedCells(C):n∈[0,0)⟩)\n  loop: \"false\"\n---\n\n\n"},{"file":"rules/renban.md","text":"---\nname: Renban\nurl: https://rules.sudoku-sleuth.com/renban.md\nkind: renban\nparameters:\n  line:\n    empty_when: edges\n    type: list<cell>\n    description: All cells of the line or cell set; order does not affect its consecutive values.\n    default: Required.\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\n  repeats:\n    type: boolean\n    description: Whether equal values may repeat.\n    default: false.\n  selection:\n    type: optional<PrefixSelection>\n    description: A prefix ending at the first target, given or listed crust; include chooses whether to keep that cell.\n    default: Absent; use the whole cell set or network.\nalias_of: value-set\nalias_bind:\n  line: line\n  edges: edges\n  selection: selection\n  channel: channel\n  repeats: repeats\n  mode: '\"consecutive\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/rotational-sums.md","text":"---\nname: Rotational Sums\nurl: https://rules.sudoku-sleuth.com/rotational-sums.md\nkind: rotational-sums\nparameters:\n  sums:\n    description: The permitted or required totals.\n    default: Required.\n    type: list<number>\nlayer: rule\nalias_of: mirrored-pairs\nalias_bind:\n  line: orderedCells({})\n  geometry: '\"rotation\"'\n  mode: '\"allowed-sum\"'\n  channel: '\"D\"'\n  sums: sums\n  centre: '\"ignore\"'\n---\n\n\n"},{"file":"rules/route-clue.md","text":"---\nname: Route Clue\nurl: https://rules.sudoku-sleuth.com/route-clue.md\nkind: route-clue\nshape: Lines\nparameters:\n  route:\n    shared:\n      role: read\n      type: route\n    type: string\n    description: The shared route name.\n    default: Required.\n  channel:\n    type: Channel\n    description: Channel supplying route numbers.\n    default: D.\n  relations:\n    type: list<PairRelation>\n    description: Inclusive alternatives required on every directed step.\n    default: Empty list; no step relation.\n  total:\n    type: optional<number>\n    description: Required sum of visited numbers.\n    default: Absent; no sum condition.\n  distinct:\n    type: boolean\n    description: Require all visited numbers to differ.\n    default: false.\n  classes:\n    type: optional<list<list<number>>>\n    description: Each full window must contain one number from each listed class.\n    default: Absent; no class windows.\n  length:\n    type: position\n    description: Window length, independent of class count.\n    default: \"3.\"\nlayer: block\ncomposition: Numeric clues over shared constructed routes.\n---\n\nClass: **existential**\n```text\nlet L=routeAnswer(route); let closed=routeClosed(route); |L|>0 ∧ (|relations|>0 → ∀i,j∈[0,|L|): next(L,i,j,closed) → relatedAny(relations,read(L[i],channel),read(L[j],channel))) ∧ (present(total) → aggregate(L,channel,\"sum\")=unwrap(total)) ∧ (distinct → repeatPolicy(L,channel,false)) ∧ (present(classes) → length>=1 ∧ ∀s∈[0,|L|): start(L,length,s,closed) ∧ (closed → |L|>0) → ∀ns∈unwrap(classes): classCount(window(L,length,s,closed),ns,channel)=1)\n\n```\n"},{"file":"rules/route-group.md","text":"---\nname: Route Group\nurl: https://rules.sudoku-sleuth.com/route-group.md\nkind: route-group\nshape: Lines\nparameters:\n  routes:\n    shared:\n      role: read\n      type: route\n    type: list<string>\n    description: Shared route names, each listed once.\n    default: Required.\n  disjoint:\n    type: boolean\n    description: Require different routes to share no cells.\n    default: true.\n  noTouch:\n    type: optional<Move>\n    description: Forbid this move between cells of different routes.\n    default: Absent; no extra separation.\n  crossings:\n    type: boolean\n    description: Allow crossings between straight steps of any length of different routes.\n    default: false.\n  cover:\n    type: optional<set<cell>>\n    description: Require the union of routes to equal this cell set.\n    default: Absent; no covering condition.\nlayer: block\ncomposition: Relations between arbitrary named routes.\n---\n\nClass: **existential**\n```text\n|routes|>=2 ∧ (∀n∈routes: |routeAnswer(n)|>0) ∧ (∀i,j∈[0,|routes|): i!=j → routes[i]!=routes[j]) ∧ (∀i,j∈[0,|routes|): i<j → let L=routeAnswer(routes[i]); let M=routeAnswer(routes[j]); (disjoint → ∀c∈L:c∉M) ∧ (present(noTouch) → ∀a∈L: ∀b∈M: ¬moveRelation(unwrap(noTouch),a,b)) ∧ (crossings ∨ ¬routeCrosses(L,M,routeClosed(routes[i]),routeClosed(routes[j])))) ∧ (present(cover) → {c∈C:∃n∈routes:c∈routeAnswer(n)}=unwrap(cover))\n\n```\n"},{"file":"rules/route.md","text":"---\nname: Route\nurl: https://rules.sudoku-sleuth.com/route.md\nkind: route\nshape: Lines\nparameters:\n  name:\n    shared:\n      role: construct\n      type: route\n    type: string\n    description: The shared route name.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: Cells the route may use.\n    default: Required.\n  move:\n    type: Move\n    description: Allowed step geometry.\n    default: orthogonal.\n  loop:\n    type: boolean\n    description: Require a simple closed cycle.\n    default: false.\n  cover:\n    type: boolean\n    description: Visit every cell in scope.\n    default: false.\n  minimum:\n    type: position\n    description: Minimum number of visited cells.\n    default: \"1.\"\n  maximum:\n    type: optional<position>\n    description: Maximum number of visited cells.\n    default: Absent; use scope size.\n  startCell:\n    type: optional<cell>\n    description: Required first cell of an open route.\n    default: Absent; either endpoint.\n  endCell:\n    type: optional<cell>\n    description: Required last cell of an open route.\n    default: Absent; either endpoint.\n  through:\n    type: set<cell>\n    description: Cells that must be visited.\n    default: Empty set.\n  requiredEdges:\n    type: list<list<cell>>\n    description: Undirected edges the route must use.\n    default: Empty list.\n  forbiddenEdges:\n    type: list<list<cell>>\n    description: Undirected edges the route must avoid.\n    default: Empty list.\n  noTouch:\n    type: optional<Move>\n    description: Forbid this move between nonconsecutive route cells.\n    default: Absent; no additional touch condition.\n  crossings:\n    type: boolean\n    description: Allow crossings between straight steps of any length.\n    default: false.\nlayer: block\ncomposition: Named path construction with configurable steps and endpoints.\n---\n\nClass: **existential**\n```text\nlet L=routeAnswer(name); simpleRoute(L,scope,move,routeClosed(name)) ∧ minimum>=1 ∧ minimum<=|L| ∧ |L|<=(if present(maximum) then unwrap(maximum) else |scope|) ∧ (cover → routeCells(L)=scope) ∧ through⊆routeCells(L) ∧ (present(startCell) → ¬loop ∧ |L|>0 ∧ L[0]=unwrap(startCell)) ∧ (present(endCell) → ¬loop ∧ |L|>0 ∧ L[|L|-1]=unwrap(endCell)) ∧ (∀e∈requiredEdges: |e|=2 ∧ routeEdge(L,e[0],e[1],loop)) ∧ (∀e∈forbiddenEdges: |e|=2 ∧ ¬routeEdge(L,e[0],e[1],loop)) ∧ (present(noTouch) → noRouteTouch(L,unwrap(noTouch),loop)) ∧ (crossings ∨ ¬routeCrosses(L,L,loop,loop))\n\n```\n"},{"file":"rules/run-sum.md","text":"---\nname: Run Sum\nurl: https://rules.sudoku-sleuth.com/run-sum.md\nkind: run-sum\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  sum:\n    description: The total the digits or values must add up to.\n    default: Required.\n    type: number\nlayer: rule\nalias_of: selected-stretch\nalias_bind:\n  cells: cells\n  selection: '\"consecutive\"'\n  sum: sum\n  count: absent(|{}|)\n  sums: ⟨n:n∈[0,0)⟩\n  crusts: absent(⟨d:d∈𝔄⟩)\n  endpointOccurrences: '\"none\"'\n---\n\n\n"},{"file":"rules/same-class.md","text":"---\nname: Same Class\nurl: https://rules.sudoku-sleuth.com/same-class.md\nkind: same-class\nparameters:\n  classes:\n    description: \"The digit classes to use: parity, remainder or alphabet thirds.\"\n    default: Required.\n    type: ClassSystem\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\nalias_of: class-pattern\nalias_bind:\n  line: orderedCells(cells)\n  edges: absent(⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩)\n  loop: \"false\"\n  classification: if classes=\"entropy\" then \"entropy\" else \"residue\"\n  modulus: if classes=\"parity\" then 2 else 3\n  length: \"3\"\n  geometry: '\"cells\"'\n  mode: '\"same\"'\n  fixedClass: absent(|{}|)\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/sandwich.md","text":"---\nname: Sandwich\nurl: https://rules.sudoku-sleuth.com/sandwich.md\nkind: sandwich\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  sum:\n    description: The total the digits or values must add up to.\n    default: Required.\n    type: number\n  endpointOccurrences:\n    description: Whether both endpoints must occur exactly once or at most once.\n    default: No extra occurrence condition.\n    type: enum{none,\"exactly-one\",\"at-most-one\"}\n  crusts:\n    description: The two crust digits that bound the sandwich.\n    default: Lowest and highest board symbols.\n    type: optional<list<digit>>\nlayer: rule\nalias_of: selected-stretch\nalias_bind:\n  cells: cells\n  selection: '\"crusts\"'\n  sum: sum\n  count: absent(|{}|)\n  sums: ⟨n:n∈[0,0)⟩\n  crusts: crusts\n  endpointOccurrences: endpointOccurrences\n---\n\n\n"},{"file":"rules/scoped-move.md","text":"---\nname: Scoped Move\nurl: https://rules.sudoku-sleuth.com/scoped-move.md\nkind: scoped-move\nparameters:\n  move:\n    description: The chess move connecting the compared cells.\n    default: Required.\n    type: Move\n  relation:\n    type: enum{same,consecutive}\n    description: \"The prohibited relationship: equal values or values one apart.\"\n    default: Required.\n  digits:\n    description: The allowed or required digits, listed explicitly; repeats in the list count where the rule says so.\n    default: Required.\n    type: list<digit>\n  scope:\n    type: set<cell>\n    description: Compare only pairs whose two cells belong to this scope.\n    default: C (the whole board).\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nalias_of: relation-scope\nalias_bind:\n  cells: scope\n  relations: ⟨relationSpec(\"difference\",if relation=\"same\" then 0 else 1):i∈[0,1)⟩\n  mode: '\"incident\"'\n  move: move\n  anchors: \"{c∈scope:D(c)∈digits}\"\n  except: ⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩\n  negative: \"true\"\n  channel: channel\nlayer: rule\n---\n\n\n"},{"file":"rules/selected-stretch.md","text":"---\nname: Selected Stretch\nurl: https://rules.sudoku-sleuth.com/selected-stretch.md\nkind: selected-stretch\nlayer: block\nparameters:\n  cells:\n    type: list<cell>\n    description: Occurrences in clue order.\n    default: Required.\n  selection:\n    type: enum{prefix,crusts,balanced,consecutive}\n    description: Select a prefix, between crusts, balanced endpoints or consecutive neighbours.\n    default: prefix.\n  sum:\n    type: number\n    description: Required selected total.\n    default: \"0.\"\n  count:\n    type: optional<position>\n    description: Explicit prefix length; otherwise use the first digit.\n    default: Absent.\n  sums:\n    type: list<number>\n    description: Required balanced endpoint totals.\n    default: Empty list.\n  crusts:\n    type: optional<list<digit>>\n    description: Custom crust digits; otherwise alphabet endpoints.\n    default: Absent.\n  endpointOccurrences:\n    type: enum{none,\"exactly-one\",\"at-most-one\"}\n    description: Default-crust occurrence policy.\n    default: none.\n---\n\nClass: **with aggregates**\n```text\nif selection=\"prefix\" then (|cells|>0 ∧ let x=if present(count) then unwrap(count) else D(cells[0]); 1<=x<=|cells| ∧ aggregate(first(cells,x),\"D\",\"sum\")=sum) else if selection=\"crusts\" then (|𝔄|>0 ∧ (if present(crusts) then\n  ∀i,j∈{t∈[0,|cells|):D(cells[t])∈unwrap(crusts)}: i<j ∧ ¬(∃k∈{t∈[0,|cells|):D(cells[t])∈unwrap(crusts)}:k<j ∧ k!=i) → aggregate(betweenPositions(cells,i,j),\"D\",\"sum\")=sum\nelse let lo=𝔄[0]; let hi=𝔄[|𝔄|-1];\n  (∀i,j∈[0,|cells|): firstOccurrence(cells,lo,i) ∧ firstOccurrence(cells,hi,j) → aggregate(betweenPositions(cells,i,j),\"D\",\"sum\")=sum)\n  ∧ (endpointOccurrences=\"exactly-one\" → countWhere(cells,λc:cell:D(c)=lo)=1 ∧ countWhere(cells,λc:cell:D(c)=hi)=1)\n  ∧ (endpointOccurrences=\"at-most-one\" → countWhere(cells,λc:cell:D(c)=lo)<=1 ∧ countWhere(cells,λc:cell:D(c)=hi)<=1))) else if selection=\"balanced\" then (∀s∈sums: ∃i,j∈[0,|cells|): i<j ∧ D(cells[i])+D(cells[j])=s\n  ∧ aggregate(betweenPositions(cells,i,j),\"D\",\"sum\")=s) else (countRun(cells)=sum)\n\n```\n"},{"file":"rules/selection.md","text":"---\nname: Selection\nurl: https://rules.sudoku-sleuth.com/selection.md\nkind: selection\nshape: Cells\nparameters:\n  name:\n    shared:\n      role: construct\n      type: selection\n    type: string\n    description: The shared selection name; H means board shading.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: The cells eligible for selection.\n    default: Required.\n  include:\n    type: set<cell>\n    description: Cells that must be selected.\n    default: Empty list.\n  exclude:\n    type: set<cell>\n    description: Cells that must be unselected.\n    default: Empty list.\n  minimum:\n    type: position\n    description: Minimum selected size.\n    default: \"0.\"\n  maximum:\n    type: optional<position>\n    description: Maximum selected size.\n    default: Absent; no upper bound.\n  groups:\n    type: list<set<cell>>\n    description: Groups with an exact selection count.\n    default: Empty list.\n  count:\n    type: position\n    description: Selected cells required in each group.\n    default: \"1.\"\nlayer: block\ncomposition: Shared subsets for other constraints to consume.\n---\n\nClass: **existential**\n```text\nlet M=selectedCells(name); M⊆scope ∧ include⊆M ∧ exclude⊆scope ∧ |exclude∩M|=0 ∧ minimum>=0 ∧ |M|>=minimum ∧ (present(maximum) → unwrap(maximum)>=minimum ∧ |M|<=unwrap(maximum)) ∧ count>=0 ∧ (∀G∈groups:G⊆scope ∧ |G∩M|=count)\n\n```\n"},{"file":"rules/shade-components.md","text":"---\nname: Shade Components\nurl: https://rules.sudoku-sleuth.com/shade-components.md\nkind: shade-components\nshape: Regions\nparameters:\n  selectionRef:\n    shared:\n      role: read\n      type: selection\n    type: string\n    description: The selection name; H means board shading.\n    default: Required.\n  name:\n    shared:\n      role: construct\n      type: partition\n    type: string\n    description: The shared partition name for the components.\n    default: Required.\n  scope:\n    type: set<cell>\n    description: The scope in which components are computed.\n    default: Required.\n  selected:\n    type: boolean\n    description: Use selected cells; false uses the complement in scope.\n    default: true.\n  count:\n    type: optional<position>\n    description: Required component count.\n    default: Absent; no count condition.\nlayer: block\ncomposition: Derive shared connected components from a selection or its complement.\n---\n\nClass: **existential**\n```text\nlet S={c∈scope:marked(selectionRef,c) ↔ selected}; let P=partitionAnswer(name); componentPartition(P,S) ∧ (present(count) → |P|=unwrap(count))\n\n```\n"},{"file":"rules/shifter-line.md","text":"---\nname: Shifter Line\nurl: https://rules.sudoku-sleuth.com/shifter-line.md\nkind: shifter-line\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n    empty_when: edges\n  edges:\n    type: optional<list<list<cell>>>\n    description: The edges of a connected network.\n    default: Absent; use the listed cells.\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\nlineGeometry(line,edges,false) ∧ (∀c∈line:D(c)!=5) ∧ (present(edges) → ∀c∈allCells(unwrap(edges)):D(c)!=5)\n∧ ∀W∈lineWindows(line,edges,2,false): |W|=2 →\n  let P=(odd(D(W[0]))↔odd(D(W[1]))); let Q=(high(D(W[0]))↔high(D(W[1])));\n  (samePartition(Regions,W[0],W[1]) → P ∧ Q) ∧ (¬samePartition(Regions,W[0],W[1]) → pairRelation(relationSpec(\"shift\",0),D(W[0]),D(W[1])))\n\n```\n"},{"file":"rules/skyscraper.md","text":"---\nname: Skyscraper\nurl: https://rules.sudoku-sleuth.com/skyscraper.md\nkind: skyscraper\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  visible:\n    description: The number of digits visible from the clue.\n    default: Required.\n    type: position\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: rule\nalias_of: blocked-sight\nalias_bind:\n  cell: absent(boardCell(1,1))\n  rays: ⟨cells:i∈[0,1)⟩\n  blockers: \"{}\"\n  includeBlocker: \"false\"\n  includeOrigin: \"false\"\n  channel: channel\n  offset: \"0\"\n  output: '\"count\"'\n  records: \"true\"\n  total: some(visible)\n  blocking: '\"listed\"'\n  targetCells: orderedCells({})\n  occurrences: \"true\"\n---\n\n\n"},{"file":"rules/slow-thermo.md","text":"---\nname: Slow Thermo\nurl: https://rules.sudoku-sleuth.com/slow-thermo.md\nkind: slow-thermo\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  orientation:\n    type: Orientation\n    description: The increasing direction of the whole line.\n    default: forward.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nalias_of: monotone-line\nalias_bind:\n  line: line\n  strict: \"false\"\n  orientation: orientation\n  channel: channel\nlayer: rule\n---\n\n\n"},{"file":"rules/split-pea.md","text":"---\nname: Split Pea\nurl: https://rules.sudoku-sleuth.com/split-pea.md\nkind: split-pea\nshape: Lines\nparameters:\n  line:\n    type: path<cell>\n    description: The full path including both endpoint circles.\n    default: Required.\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n|line|>=2 ∧ reversibleDecimal(⟨line[i]:i∈[0,|line|), i=0 ∨ i=|line|-1⟩,aggregate(betweenPositions(line,0,|line|-1),\"D\",\"sum\"))\n\n```\n"},{"file":"rules/subset-total.md","text":"---\nname: Subset Total\nurl: https://rules.sudoku-sleuth.com/subset-total.md\nkind: subset-total\nshape: Cages\nparameters:\n  cells:\n    type: set<cell>\n    description: Cells from which to select a nonempty subset.\n    default: Required.\n  total:\n    type: number\n    description: The selected sum.\n    default: Required.\n  forbid:\n    type: boolean\n    description: Require the absence of such a subset.\n    default: false.\n  minimum:\n    type: position\n    description: Minimum subset size.\n    default: \"1.\"\n  maximum:\n    type: optional<position>\n    description: Maximum subset size.\n    default: Absent; use the whole scope size.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: block\ncomposition: Existential subset selection with total and size bounds.\n---\n\nClass: **existential**\n```text\nminimum>=1 ∧ let has=(∃S:set<cell>: S⊆cells ∧ minimum<=|S| ∧ |S|<=(if present(maximum) then unwrap(maximum) else |cells|) ∧ aggregate(S,channel,\"sum\")=total); if forbid then ¬has else has\n\n```\n"},{"file":"rules/sudoku.md","text":"---\nname: Sudoku\nurl: https://rules.sudoku-sleuth.com/sudoku.md\nparameters:\n  board:\n    type: record{rows:position,cols:position}\n    description: The board dimensions and standard boxes; write 9x9.\n    default: Required.\n    syntax:\n      form: dimensions\nkind: sudoku\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\nrows=9 ∧ cols=9 ∧ board.rows=rows ∧ board.cols=cols ∧ (∀c∈C:D(c)∈[1,10)) ∧ (∀house∈standardHouses(): |house|=9 ∧ repeatPolicy(house,\"D\",false)) ∧ (∀c∈C: given(c) → D(c)=givenValue(c))\n\n```\n"},{"file":"rules/sum-free-cage.md","text":"---\nname: Sum Free Cage\nurl: https://rules.sudoku-sleuth.com/sum-free-cage.md\nkind: sum-free-cage\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  modulus:\n    description: The divisor used to take remainders.\n    default: Required. modulus ≥ 1.\n    type: position\nlayer: rule\nalias_of: digit-profile\nalias_bind:\n  cells: orderedCells(cells)\n  classes: ⟨⟨d:d∈𝔄⟩:i∈[0,0)⟩\n  counts: ⟨i:i∈[0,0)⟩\n  exhaustive: \"false\"\n  channel: '\"D\"'\n  selfCount: \"false\"\n  windowLength: absent(|{}|)\n  loop: \"false\"\n  comparison: '\"exact\"'\n  maximumDistinct: absent(0)\n  repeats: \"false\"\n  balancePairs: ⟨⟨d:d∈𝔄⟩:i∈[0,0)⟩\n  sumFree: some(modulus)\n---\n\n\n"},{"file":"rules/sum-partition.md","text":"---\nname: Sum Partition\nurl: https://rules.sudoku-sleuth.com/sum-partition.md\nkind: sum-partition\nshape: Lines\nparameters:\n  line:\n    type: path<cell>\n    description: The ordered line.\n    default: Required.\n  total:\n    type: number\n    description: The sum required for every segment.\n    default: Required.\n  mode:\n    type: enum{cover,partition}\n    description: Cover every position with a target-sum interval, or partition the whole line into disjoint target-sum intervals.\n    default: Required.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\n  repeats:\n    type: boolean\n    description: Whether numbers may repeat inside a segment.\n    default: true.\n  loop:\n    type: boolean\n    description: Whether intervals may cross the last-to-first join.\n    default: false.\nlayer: block\ncomposition: Partition ordered lists into configurable target-total segments.\n---\n\nClass: **existential**\n```text\n((|line| > 0) and if (mode = \"partition\") then if loop then exists s∈[0,|line|): partitionSums(cyclicCut(line,s),total,channel,repeats) else partitionSums(line,total,channel,repeats) else if loop then forall i∈[0,|line|): exists s∈[0,|line|): exists k∈[1,(|line| + 1)): (((start(line,k,s,true) and exists j∈[0,k): (rem((s + j),|line|) = i)) and repeatPolicy(window(line,k,s,true),channel,repeats)) and (aggregate(window(line,k,s,true),channel,\"sum\") = total)) else forall i∈[0,|line|): exists a∈[0,|line|): exists b∈[(a + 1),(|line| + 1)): (((a <= i) and (i < b)) and sumSegment(line,a,b,total,channel,repeats)))\n\n```\n"},{"file":"rules/summit.md","text":"---\nname: Summit\nurl: https://rules.sudoku-sleuth.com/summit.md\nkind: summit\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: All edges of one connected network.\n    default: Absent; use the ordered line.\nlayer: rule\nalias_of: difference-line\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  mode: '\"turning\"'\n  channel: '\"D\"'\n  diamonds: \"{}\"\n  gap: \"0\"\n  turnDigits: \"{1,9}\"\n---\n\n\n"},{"file":"rules/symbol-house.md","text":"---\nname: Symbol House\nurl: https://rules.sudoku-sleuth.com/symbol-house.md\nkind: symbol-house\nshape: Regions\nparameters:\n  symbols:\n    shared:\n      role: read\n      type: symbol\n    type: string\n    description: Symbol channel name; D reads one face digit per cell.\n    default: '\"D\".'\n  houses:\n    type: list<set<cell>>\n    description: Groups whose symbol multiplicities are constrained.\n    default: Required.\n  digits:\n    type: list<digit>\n    description: Distinct symbols to count.\n    default: Required.\n  counts:\n    type: list<position>\n    description: Exact counts in the same order as digits.\n    default: Required.\nlayer: block\ncomposition: Multiplicity constraints over arbitrary symbol channels and houses.\n---\n\nClass: **existential**\n```text\n|digits|=|counts| ∧ allDifferent(digits,λd:digit:d) ∧ (∀d∈digits:d∈𝔄) ∧ (∀n∈counts:n>=0) ∧ ∀G∈houses: (∀c∈G:∀d∈cellSymbols(symbols,c):d∈digits) ∧ (∀i∈[0,|digits|): 0<=i ∧ i<|counts| ∧ (Σ_{c∈G}countWhere(cellSymbols(symbols,c),λd:digit:d=digits[i]))=counts[i])\n\n```\n"},{"file":"rules/tardis.md","text":"---\nname: Tardis\nurl: https://rules.sudoku-sleuth.com/tardis.md\nkind: tardis\nparameters:\n  cell:\n    description: The clue cell.\n    default: Required.\n    type: cell\n  neighbours:\n    description: The cells counted or compared around the clue.\n    default: Required. neighbours disjoint from {cell}.\n    type: set<cell>\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: D.\nlayer: rule\nalias_of: neighbour-extremum\nalias_bind:\n  type: '\"max\"'\n  cells: \"{cell}\"\n  exhaustive: \"false\"\n  neighbourhood: '\"orthogonal\"'\n  boundary: \"false\"\n  channel: channel\n  neighbours: some(neighbours)\n---\n\n\n"},{"file":"rules/thermo.md","text":"---\nname: Thermo\nurl: https://rules.sudoku-sleuth.com/thermo.md\nkind: thermo\nparameters:\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  strict:\n    type: boolean\n    description: Whether each step must strictly increase.\n    default: true.\n  orientation:\n    type: Orientation\n    description: Read forwards, backwards, or choose either direction for the whole line.\n    default: forward.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\nlayer: rule\nalias_of: monotone-line\nalias_bind:\n  line: line\n  strict: strict\n  orientation: orientation\n  channel: channel\n---\n\n\n"},{"file":"rules/unique.md","text":"---\nname: Unique\nurl: https://rules.sudoku-sleuth.com/unique.md\nkind: unique\nalias_of: regions\n---\n\n\n"},{"file":"rules/value-modifier.md","text":"---\nname: Value Modifier\nurl: https://rules.sudoku-sleuth.com/value-modifier.md\nkind: value-modifier\nparameters:\n  factor:\n    description: The multiplier for a modified digit.\n    default: Required.\n    type: number\n  offset:\n    description: The amount added after multiplication.\n    default: Required.\n    type: number\n  exactly:\n    description: The cells in each group and the exact number that must be modified.\n    default: Required.\n    type: list<set<cell>>\n  count:\n    description: The number of cells or occurrences to count.\n    default: Required.\n    type: position\n  atMostOne:\n    description: The cells in each group that may contain at most one modified cell.\n    default: Required.\n    empty_when: exactly\n    type: list<set<cell>>\n  distinct:\n    description: Whether modified cells must contain different digits.\n    default: Required.\n    type: boolean\nlayer: block\ncomposition: Compose modified value channels with configurable group counts.\n---\n\nClass: **existential**\n```text\n∃M:set<cell>: M⊆C ∧\n(∀G∈exactly: |G∩M|=count) ∧ (∀G∈atMostOne: |G∩M|<=1)\n∧ (distinct → repeatPolicy(M,\"D\",false))\n∧ (∀c∈C: (c∈M → V(c)=affineValue(c,factor,offset)) ∧ (c∉M → V(c)=D(c)))\n∧ (∀meaning∈ValuedRuleMeanings: meaning)\n\n```\n"},{"file":"rules/value-set.md","text":"---\nname: Value Set\nurl: https://rules.sudoku-sleuth.com/value-set.md\nkind: value-set\nshape: Lines\nparameters:\n  line:\n    empty_when: edges\n    type: list<cell>\n    description: All cells of the line or cell set; order does not affect its consecutive values.\n    default: Required.\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\n  channel:\n    type: Channel\n    description: Read printed digits (D) or effective values (V).\n    default: V.\n  repeats:\n    type: boolean\n    description: Whether equal values may repeat.\n    default: false.\n  selection:\n    type: optional<PrefixSelection>\n    description: A prefix ending at the first target, given or listed crust; include chooses whether to keep that cell.\n    default: Absent; use the whole cell set or network.\n  mode:\n    type: enum{consecutive,nonconsecutive,separated}\n    description: Consecutive support, no difference of one, or all differences greater than one.\n    default: consecutive.\nlayer: block\n---\n\nClass: **with aggregates**\n```text\nif present(selection) then ((not(present(edges)) and selectionValid(line,unwrap(selection),channel)) and valueSet(selectedPrefix(line,unwrap(selection),channel),channel,repeats,mode)) else (lineGeometry(line,edges,false) and if present(edges) then valueSet(allCells(unwrap(edges)),channel,repeats,mode) else valueSet(line,channel,repeats,mode))\n\n```\n"},{"file":"rules/vault.md","text":"---\nname: Vault\nurl: https://rules.sudoku-sleuth.com/vault.md\nkind: vault\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: set<cell>\n  sum:\n    description: The total the digits or values must add up to.\n    default: No total imposed.\n    type: optional<number>\n  neighbours:\n    description: The cells counted or compared around the clue.\n    default: Required. neighbours disjoint from cells.\n    type: set<cell>\nlayer: rule\n---\n\nClass: **with aggregates**\n```text\n(∀a∈cells: ∀b∈neighbours: D(a)!=D(b)) ∧ (present(sum) → aggregate(cells,\"D\",\"sum\")=unwrap(sum))\n\n```\n"},{"file":"rules/whisper.md","text":"---\nname: Whisper\nurl: https://rules.sudoku-sleuth.com/whisper.md\nkind: whisper\nalias_of: whispers\n---\n\n\n"},{"file":"rules/whispers-4.md","text":"---\nname: Whispers 4\naliases: [Dutch Whispers]\nurl: https://rules.sudoku-sleuth.com/whispers-4.md\nkind: whispers-4\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: difference-line\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  mode: '\"at-least\"'\n  channel: '\"V\"'\n  diamonds: \"{}\"\n  gap: \"4\"\n  turnDigits: \"{}\"\nlayer: rule\n---\n\n\n"},{"file":"rules/whispers-5.md","text":"---\nname: Whispers 5\naliases: [German Whispers]\nurl: https://rules.sudoku-sleuth.com/whispers-5.md\nkind: whispers-5\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: difference-line\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  mode: '\"at-least\"'\n  channel: '\"V\"'\n  diamonds: \"{}\"\n  gap: \"5\"\n  turnDigits: \"{}\"\nlayer: rule\n---\n\n\n"},{"file":"rules/whispers.md","text":"---\nname: Whispers\nurl: https://rules.sudoku-sleuth.com/whispers.md\nkind: whispers\nparameters:\n  line:\n    empty_when: edges\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\n  gap:\n    description: \"The least difference between neighbouring values.\"\n    default: Required.\n    type: number\n  loop:\n    description: Whether the line closes, joining its last cell back to its first.\n    default: false (open path).\n    type: boolean\n  edges:\n    type: optional<list<list<cell>>>\n    description: Explicit undirected edges of one connected network; each edge lists two different cells.\n    default: Absent; use the ordered line.\nalias_of: difference-line\nalias_bind:\n  line: line\n  edges: edges\n  loop: loop\n  mode: '\"at-least\"'\n  channel: '\"V\"'\n  diamonds: \"{}\"\n  gap: gap\n  turnDigits: \"{}\"\nlayer: rule\n---\n\n\n"},{"file":"rules/window-classes.md","text":"---\nname: Window Classes\nurl: https://rules.sudoku-sleuth.com/window-classes.md\nkind: window-classes\nparameters:\n  classes:\n    description: \"The digit classes to use: parity, remainder or alphabet thirds.\"\n    default: Required.\n    type: ClassSystem\nalias_of: class-pattern\nalias_bind:\n  line: ⟨c:c∈orderedCells(C),false⟩\n  edges: absent(⟨⟨c:c∈orderedCells(C),false⟩:i∈[0,0)⟩)\n  loop: \"false\"\n  classification: if classes=\"entropy\" then \"entropy\" else \"residue\"\n  modulus: if classes=\"parity\" then 2 else 3\n  length: \"3\"\n  geometry: '\"squares\"'\n  mode: '\"cover\"'\n  fixedClass: absent(|{}|)\n  channel: '\"D\"'\nlayer: rule\n---\n\n\n"},{"file":"rules/x-sum.md","text":"---\nname: X Sum\nurl: https://rules.sudoku-sleuth.com/x-sum.md\nkind: x-sum\nparameters:\n  cells:\n    description: The marked cells, for example r1c1-r1c2-r2c2.\n    default: Required.\n    type: list<cell>\n  sum:\n    description: The total the digits or values must add up to.\n    default: Required.\n    type: number\n  count:\n    description: The number of cells or occurrences to count.\n    default: First digit supplies the extent.\n    type: optional<position>\nlayer: rule\nalias_of: selected-stretch\nalias_bind:\n  cells: cells\n  selection: '\"prefix\"'\n  sum: sum\n  count: count\n  sums: ⟨n:n∈[0,0)⟩\n  crusts: absent(⟨d:d∈𝔄⟩)\n  endpointOccurrences: '\"none\"'\n---\n\n\n"},{"file":"rules/xv.md","text":"---\nname: XV\nurl: https://rules.sudoku-sleuth.com/xv.md\nkind: xv\naliases: [X and V, XV clues]\nshape: Edges\nparameters:\n  cells:\n    description: The two marked cells in order, for example r1c1-r1c2.\n    default: Empty list.\n    type: list<cell>\n    syntax:\n      form: cells\n      count: 2\n  mark:\n    type: enum{x,v}\n    description: X gives a sum of ten; V gives a sum of five.\n    default: '\"x\".'\n    syntax:\n      form: keywords\n      named: true\n      choices:\n        x: {}\n        v: {}\n  x:\n    type: list<list<cell>>\n    description: Pairs marked x; each pair has exactly two cells.\n    default: Empty list.\n  v:\n    type: list<list<cell>>\n    description: Pairs marked v; each pair has exactly two cells.\n    default: Empty list.\n  allGiven:\n    type: list<enum{x,v}>\n    description: Kinds for which every possible orthogonal mark is given.\n    default: Empty list.\nalias_of: marked-pairs\nalias_bind:\n  x: 'if |cells|>0 ∧ mark=\"x\" then ⟨if i<|x| then x[i] else cells:i∈[0,|x|+1)⟩ else x'\n  v: 'if |cells|>0 ∧ mark=\"v\" then ⟨if i<|v| then v[i] else cells:i∈[0,|v|+1)⟩ else v'\n  white: '⟨cells:i∈[0,0)⟩'\n  black: '⟨cells:i∈[0,0)⟩'\n  allGiven: allGiven\nlayer: rule\n---\n\n\n"},{"file":"rules/yin-yang.md","text":"---\nname: Yin Yang\nurl: https://rules.sudoku-sleuth.com/yin-yang.md\nkind: yin-yang\nparameters: {}\nlayer: rule\n---\n\nClass: **existential**\n```text\nconnected({c ∈ C: marked(\"H\",c)}) ∧ connected({c ∈ C: ¬marked(\"H\",c)})\n∧ ∀r ∈ [0,rows−1): ∀k ∈ [0,cols−1):\n  (∃a ∈ window2(r,k): marked(\"H\",a)) ∧ (∃b ∈ window2(r,k): ¬marked(\"H\",b))\n\n```\n"},{"file":"rules/zipper.md","text":"---\nname: Zipper\nurl: https://rules.sudoku-sleuth.com/zipper.md\nkind: zipper\nparameters:\n  centre:\n    description: Whether pair sums equal the centre on odd lines, ignore it, or require an odd-length line with a centre.\n    default: when-odd.\n    type: enum{\"when-odd\",ignore,required}\n  line:\n    description: The cells in order, for example r1c1-r1c2-r1c3.\n    default: Required.\n    type: path<cell>\nlayer: rule\nalias_of: mirrored-pairs\nalias_bind:\n  line: line\n  geometry: '\"line\"'\n  mode: '\"equal-sum\"'\n  channel: '\"D\"'\n  sums: ⟨n:n∈[0,0)⟩\n  centre: centre\n---\n\n\n"}];
let cached:PublicLibrary|undefined;
export function evaluatorLibrary():PublicLibrary {
 if(cached)return cached;
 const result=compilePublicLibrary([{file:'rules/predicates.md',text:'---\ndocument: prelude\n---\n'},...sources],()=>({value:defaultCasePrelude(),diagnostics:[]}));
 if(!result.value)throw new Error(JSON.stringify(result.diagnostics));
 return cached=result.value;
}
